-- ===== supabase/migrations/20261204010100_macro_events.sql =====
-- =============================================================================
-- NEXA · 10100 · Size, risk and the world outside (ADR-209)
-- =============================================================================
-- Mirrors src/lib/sim/macro.ts (saturationFactor, overheadShare, frictionModifiers, combineModifiers, sizeDecades,
-- sizedChancePerDay, sizedChanceShare, sizedSeverityUniform, countryFactor, sizedWeight, sizeUnitCents,
-- effectiveCoverage, eventSnapshot), eventModifiers of src/lib/sim/company-events.ts (insurance and leader share) and
-- advisorWageCents / progressiveTaxCents of src/lib/sim/listed.ts. Values: game_config "macro" (src/config/macro.ts),
-- "companyEvents" (15 external archetypes) and "listed" (taxes.brackets, taxes.advisor).
--
-- * World map contract (ADR-208): company_country(uuid), country_cfg(text) and company_is_market_leader(uuid) are
--   created as neutral stubs only when the world migration is missing; without a headquarters every factor is 1.
-- * player_companies: insurance_level / insurance_prev_level / insurance_changed_at, lobby_level.
-- * Hooks instead of copies where possible:
--   - player_company_events BEFORE INSERT: snapshot of insurance coverage, lobby bonus and market-leader share into
--     the event's definition (every way an event starts: daily roll, tax audit, tests).
--   - player_company_events AFTER UPDATE: a won lobby strategy ("lobby…") raises the lobby level.
--   - company_event_hour_effect (only caller: player_company_close_hour) returns the event modifiers times the size
--     friction (saturation, overhead, insurance premium), extra costs capped. close_hour stays untouched.
-- * Redefined (latest versions copied): company_event_modifiers (m4h), company_event_unit_cents (0700: + revenue share),
--   company_event_roll (m4h: size, country and lobby), listed_advisor_wage (5400: exponential), listed_books_do and
--   listed_books_preview (5410: progressive brackets, world tax rate when present).
-- * RPCs: get_company_risks (the "Risiken" card), set_company_insurance.
-- Idempotent: runs unchanged as supabase/updates/20261204010100_macro_events.sql.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. World map contract (ADR-208): neutral stubs when that migration is not there
-- ---------------------------------------------------------------------------
do $$
begin
  if to_regprocedure('public.company_country(uuid)') is null then
    execute $f$create function public.company_country(p_company uuid) returns text language sql stable
              security definer set search_path = '' as 'select null::text'$f$;
    execute 'revoke all on function public.company_country(uuid) from public, anon, authenticated';
  end if;
  if to_regprocedure('public.country_cfg(text)') is null then
    execute $f$create function public.country_cfg(p_country text) returns jsonb language sql stable
              security definer set search_path = '' as 'select null::jsonb'$f$;
    execute 'revoke all on function public.country_cfg(text) from public, anon, authenticated';
  end if;
  if to_regprocedure('public.company_is_market_leader(uuid)') is null then
    execute $f$create function public.company_is_market_leader(p_company uuid) returns boolean language sql stable
              security definer set search_path = '' as 'select false'$f$;
    execute 'revoke all on function public.company_is_market_leader(uuid) from public, anon, authenticated';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- B. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists insurance_level smallint not null default 0;
alter table public.player_companies add column if not exists insurance_prev_level smallint not null default 0;
alter table public.player_companies add column if not exists insurance_changed_at timestamptz;
alter table public.player_companies add column if not exists lobby_level smallint not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_insurance_level_chk'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_insurance_level_chk
      check (insurance_level between 0 and 9 and insurance_prev_level between 0 and 9 and lobby_level between 0 and 99);
  end if;
end;
$$;
comment on column public.player_companies.insurance_level is
  'Insurance against disasters and cyber attacks (ADR-209): index into game_config macro.insurance.levels; premium as a '
  'share of the own revenue every hour, coverage fixed when an event starts.';
comment on column public.player_companies.lobby_level is
  'Lobby level (ADR-209): +1 for every won lobby strategy, raises lobby step chances and lowers political events.';

-- ---------------------------------------------------------------------------
-- C. Formulas (src/lib/sim/macro.ts)
-- ---------------------------------------------------------------------------
create or replace function public.macro_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('macro'), '{}'::jsonb);
$$;

-- sizeDecades: log10(value / pivot), 0..maxDecades
create or replace function public.macro_size_decades(p_worth bigint)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select case when coalesce(p_worth, 0) <= public.cfg_num(c, '{events,worthPivotCents}', 2000000000) then 0
              else least(public.cfg_num(c, '{events,maxDecades}', 3),
                         log(p_worth::numeric / public.cfg_num(c, '{events,worthPivotCents}', 2000000000)::numeric)::double precision) end
    from (select public.macro_cfg() as c) x;
$$;

-- frictionModifiers: {demand_factor, extra_cost_share} of size and insurance
create or replace function public.macro_friction(p_worth bigint, p_insurance integer)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'demand_factor', case when coalesce(p_worth, 0) <= y.pivot then 1.0
                          else power(y.pivot / p_worth::double precision, 1 - public.cfg_num(y.c, '{friction,saturationExponent}', 0.4)) end,
    'extra_cost_share',
      (case when coalesce(p_worth, 0) <= y.pivot then 0
            else least(public.cfg_num(y.c, '{friction,overheadMaxBps}', 4000),
                       public.cfg_num(y.c, '{friction,overheadPerDecadeBps}', 1500) * log(p_worth::numeric / y.pivot::numeric)::double precision) end
       + public.cfg_num(y.c, array['insurance', 'levels', greatest(0, least(coalesce(p_insurance, 0), y.n - 1))::text, 'premiumBps'], 0)) / 10000.0)
    from (select c, public.cfg_num(c, '{friction,worthPivotCents}', 3000000000) as pivot,
                 greatest(1, jsonb_array_length(coalesce(c #> '{insurance,levels}', '[{}]'::jsonb))) as n
            from (select public.macro_cfg() as c) z) y;
$$;

-- countryFactor: country risk of the headquarters on an archetype's weight (1 without headquarters)
create or replace function public.macro_country_factor(p_arch jsonb, p_country jsonb)
returns double precision
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  c      jsonb := coalesce(public.macro_cfg() -> 'country', '{}'::jsonb);
  v_risk text := p_arch ->> 'risk';
  v_kinds jsonb := '[]'::jsonb;
  d      jsonb;
  k      text;
begin
  if p_country is null or jsonb_typeof(p_country) <> 'object' or v_risk is null then
    return 1;
  end if;
  if v_risk = 'political' then
    return 1 + public.cfg_num(c, '{politicalBoost}', 2) * least(1, greatest(0, public.cfg_num(p_country, '{politicalRisk}', 0) / 100));
  elsif v_risk = 'tariff' then
    return 1 + public.cfg_num(c, '{tariffBoost}', 2) * least(1, greatest(0, public.cfg_num(p_country, '{tariffExposure}', 0) / 100));
  elsif v_risk = 'war' then
    return 1 + public.cfg_num(c, '{warBoost}', 3) * least(1, greatest(0, public.cfg_num(p_country, '{warRisk}', 0) / 100));
  elsif v_risk = 'image' then
    return 1 + public.cfg_num(c, '{imageBoost}', 1) * least(1, greatest(0, -public.cfg_num(p_country, '{imageBps}', 0) / 10000));
  elsif v_risk = 'disaster' then
    if jsonb_typeof(p_country -> 'disasterRisk') is distinct from 'array' or jsonb_array_length(p_country -> 'disasterRisk') = 0 then
      return 1;
    end if;
    for d in select x from jsonb_array_elements(p_country -> 'disasterRisk') x loop
      k := case jsonb_typeof(d) when 'string' then d #>> '{}' else coalesce(d ->> 'kind', d ->> 'key') end;
      continue when k is null;
      v_kinds := v_kinds || coalesce(c #> array['disasterMap', k], jsonb_build_array(k));
    end loop;
    return case when v_kinds ? (p_arch ->> 'key') then public.cfg_num(c, '{disasterListed}', 2.5)
                else public.cfg_num(c, '{disasterOther}', 0.4) end;
  end if;
  return 1;
end;
$$;

-- sizedWeight: internal archetypes unchanged; external ones from minWorthCents, × size × country × lobby (political)
create or replace function public.macro_weight(p_arch jsonb, p_worth bigint, p_country jsonb, p_lobby integer)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when coalesce((p_arch ->> 'external')::boolean, false) is not true then greatest(0, public.cfg_num(p_arch, '{weight}', 0))
    when coalesce(p_worth, 0) < public.cfg_num(p_arch, '{minWorthCents}', 0) then 0
    else greatest(0, public.cfg_num(p_arch, '{weight}', 0))
         * (1 + public.cfg_num(m, '{events,externalBoostPerDecade}', 1) * public.macro_size_decades(p_worth))
         * public.macro_country_factor(p_arch, p_country)
         * case when p_arch ->> 'risk' = 'political'
                then greatest(0, 1 - least(greatest(coalesce(p_lobby, 0), 0), public.cfg_num(m, '{lobby,maxLevel}', 5))
                                     * public.cfg_num(m, '{lobby,politicalCutPerLevel}', 0.12))
                else 1 end
  end
    from (select public.macro_cfg() as m) x;
$$;

-- The country config of a company's headquarters (null without)
create or replace function public.macro_company_country(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when public.company_country(p_company) is null then null
              else public.country_cfg(public.company_country(p_company)) end;
$$;

-- pickArchetype with the size context (catalog order)
create or replace function public.company_event_pick_sized(p_u double precision, p_sector text, p_polarity text,
                                                           p_worth bigint, p_country jsonb, p_lobby integer)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_total double precision := 0;
  v_x     double precision;
  r       record;
  v_last  jsonb;
begin
  select coalesce(sum(public.macro_weight(t.x, p_worth, p_country, p_lobby)), 0) into v_total
    from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) t(x)
   where t.x ->> 'polarity' = p_polarity
     and (jsonb_typeof(t.x -> 'sectors') is distinct from 'array' or t.x -> 'sectors' ? p_sector);
  if v_total <= 0 then
    return null;
  end if;
  v_x := least(greatest(coalesce(p_u, 0), 0), 0.999999) * v_total;
  for r in
    select t.x, public.macro_weight(t.x, p_worth, p_country, p_lobby) as w
      from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) with ordinality t(x, ord)
     where t.x ->> 'polarity' = p_polarity
       and (jsonb_typeof(t.x -> 'sectors') is distinct from 'array' or t.x -> 'sectors' ? p_sector)
     order by t.ord
  loop
    continue when r.w <= 0;
    v_x := v_x - r.w;
    if v_x < 0 then
      return r.x;
    end if;
    v_last := r.x;
  end loop;
  return v_last;
end;
$$;

-- pickArchetype without size (m4h signature): the pick of a small company, never an external event
create or replace function public.company_event_pick(p_u double precision, p_sector text, p_polarity text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select public.company_event_pick_sized(p_u, p_sector, p_polarity, 0, null, 0);
$$;

-- effectiveCoverage of a company right now (insurance coverage 0..1)
create or replace function public.macro_coverage(p_company uuid, p_at timestamptz default null)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select public.cfg_num(m, array['insurance', 'levels',
           greatest(0, least(case when pc.insurance_changed_at is null
                                       or pc.insurance_changed_at
                                          + make_interval(secs => public.cfg_num(m, '{insurance,changeWaitHours}', 12) * 3600)
                                          <= coalesce(p_at, public.game_now())
                                  then pc.insurance_level
                                  else least(pc.insurance_level, pc.insurance_prev_level) end,
                             jsonb_array_length(coalesce(m #> '{insurance,levels}', '[{}]'::jsonb)) - 1))::text, 'coverage'], 0)
    from public.player_companies pc, (select public.macro_cfg() as m) x
   where pc.company_id = p_company;
$$;

-- ---------------------------------------------------------------------------
-- D. Event hooks: snapshot at the start, lobby level on a win
-- ---------------------------------------------------------------------------
-- eventSnapshot: insurance coverage (insurable crises), lobby bonus on lobby steps, market-leader share (political)
create or replace function public.macro_event_snapshot_trg()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  m       jsonb := public.macro_cfg();
  v_def   jsonb := new.definition;
  v_lobby integer;
  v_bonus integer;
  v_lead  double precision := 0;
  v_strats jsonb;
begin
  if v_def is null or new.polarity <> 'crisis' then
    return new;
  end if;
  if coalesce((v_def ->> 'insurable')::boolean, false) then
    v_def := v_def || jsonb_build_object('insuredShare', least(1, greatest(0, coalesce(public.macro_coverage(new.company_id, new.started_at), 0))));
  end if;
  select pc.lobby_level into v_lobby from public.player_companies pc where pc.company_id = new.company_id;
  v_bonus := (least(greatest(coalesce(v_lobby, 0), 0), public.cfg_num(m, '{lobby,maxLevel}', 5))
              * public.cfg_num(m, '{lobby,successBpsPerLevel}', 350))::integer;
  if v_bonus > 0 and jsonb_typeof(v_def -> 'strategies') = 'array' then
    select jsonb_agg(case when s ->> 'key' like 'lobby%' and jsonb_typeof(s -> 'steps') = 'array'
                          then jsonb_set(s, '{steps}', (select coalesce(jsonb_agg(st || jsonb_build_object('baseBps',
                                                                 greatest((st ->> 'baseBps')::integer, least(9500, (st ->> 'baseBps')::integer + v_bonus)))
                                                                 order by o), '[]'::jsonb)
                                                          from jsonb_array_elements(s -> 'steps') with ordinality q(st, o)))
                          else s end order by ord)
      into v_strats
      from jsonb_array_elements(v_def -> 'strategies') with ordinality t(s, ord);
    v_def := jsonb_set(v_def, '{strategies}', v_strats);
  end if;
  if v_def ->> 'risk' = 'political' and coalesce(public.company_is_market_leader(new.company_id), false) then
    v_lead := least(1, greatest(0, coalesce((select (g.value #>> '{lobby,politicalImpactReductionBps}')::double precision
                                               from public.game_config g where g.key = 'world'), 3000) / 10000));
    v_def := v_def || jsonb_build_object('leaderShare', v_lead);
  end if;
  new.definition := v_def;
  return new;
end;
$$;
drop trigger if exists macro_event_snapshot on public.player_company_events;
create trigger macro_event_snapshot before insert on public.player_company_events
  for each row execute function public.macro_event_snapshot_trg();

-- A won lobby strategy raises the lobby level (at most lobby.maxLevel)
create or replace function public.macro_lobby_win_trg()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'solved' and old.status is distinct from 'solved' and new.polarity = 'crisis'
     and coalesce(new.strategy, '') like 'lobby%' then
    update public.player_companies
       set lobby_level = least(public.cfg_num(public.macro_cfg(), '{lobby,maxLevel}', 5)::integer, lobby_level + 1)
     where company_id = new.company_id;
    perform public.company_news_add(new.company_id, 'lobby_level',
      jsonb_build_object('event_id', new.id, 'archetype', new.archetype,
                         'level', (select pc.lobby_level from public.player_companies pc where pc.company_id = new.company_id)));
  end if;
  return new;
end;
$$;
drop trigger if exists macro_lobby_win on public.player_company_events;
create trigger macro_lobby_win after update of status on public.player_company_events
  for each row execute function public.macro_lobby_win_trg();

-- ---------------------------------------------------------------------------
-- E. The hour: event modifiers with insurance and leader share, times the size friction
-- ---------------------------------------------------------------------------
-- eventModifiers (copied from m4h): the effect shrinks by the insured and the leader share
create or replace function public.company_event_modifiers(p_def jsonb, p_severity integer, p_phase text, p_mitigation double precision,
                                                          p_capacity_hit double precision default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cfg   jsonb := public.company_events_cfg();
  v_scale double precision;
  v_share double precision := 0;
  v_s     double precision;
  v_m     double precision := least(1, greatest(0, coalesce(p_mitigation, 0)));
  v_cover double precision := 0;
begin
  v_scale := public.cfg_num(v_cfg, array['severityScale', (p_severity - 1)::text],
                            case p_severity when 1 then 1 when 2 then 1.7 else 2.5 end);
  if p_def ->> 'polarity' = 'crisis' then
    if p_phase = 'open' then
      v_share := public.cfg_num(v_cfg, '{preDeadlineShare}', 0.25) * (1 - v_m);
    elsif p_phase = 'in_force' then
      v_share := 1 - v_m;
    end if;
    -- ADR-209: insurance and market leadership take their share (fixed when the event started)
    v_cover := 1 - (1 - least(1, greatest(0, public.cfg_num(p_def, '{insuredShare}', 0))))
                 * (1 - least(1, greatest(0, public.cfg_num(p_def, '{leaderShare}', 0))));
  elsif p_phase = 'in_force' then
    v_share := v_m;
  end if;
  v_s := v_share * v_scale * (1 - v_cover);
  return jsonb_build_object(
    'demand_factor', greatest(0.05, 1 + public.cfg_num(p_def, '{effect,demand}', 0) * v_s),
    'capacity_factor', greatest(0.05, (1 + public.cfg_num(p_def, '{effect,capacity}', 0) * v_s)
                                      * (1 - least(0.9, greatest(0, coalesce(p_capacity_hit, 0))))),
    'extra_cost_share', public.cfg_num(p_def, '{effect,cost}', 0) * v_s);
end;
$$;

-- The effect on one operating hour (copied from m4h) times the size friction (combineModifiers)
create or replace function public.company_event_hour_effect(p_company uuid, p_from timestamptz, p_to timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  e       public.player_company_events;
  v_hit   double precision;
  v_phase text;
  v_ev    jsonb := jsonb_build_object('event_id', null, 'demand_factor', 1, 'capacity_factor', 1, 'extra_cost_share', 0);
  v_fr    jsonb;
begin
  select * into e from public.player_company_events ev
   where ev.company_id = p_company and ev.started_at < p_to
   order by ev.started_at desc limit 1;
  if e.id is not null then
    v_phase := public.company_event_phase(e.polarity, public.cfg_num(e.definition, '{lastsHours}', 0), e.deadline_at,
                                          e.resolved_at, p_from);
    select coalesce(sum(s.capacity_hit * extract(epoch from (least(s.ends_at, p_to) - greatest(s.started_at, p_from)))
                        / greatest(1, extract(epoch from (p_to - p_from)))), 0)
      into v_hit
      from public.company_event_steps s
     where s.event_id = e.id and s.capacity_hit > 0 and s.started_at < p_to and s.ends_at > p_from;
    if v_phase <> 'over' or v_hit > 0 then
      v_ev := public.company_event_modifiers(e.definition, e.severity, v_phase, e.mitigation, v_hit)
              || jsonb_build_object('event_id', e.id);
    end if;
  end if;
  -- ADR-209: saturation, overhead and the insurance premium of the company's size
  v_fr := public.macro_friction(public.company_worth_cents(p_company),
                                (select pc.insurance_level from public.player_companies pc where pc.company_id = p_company));
  return v_ev || jsonb_build_object(
    'demand_factor', (v_ev ->> 'demand_factor')::double precision * (v_fr ->> 'demand_factor')::double precision,
    'extra_cost_share', least(public.cfg_num(public.macro_cfg(), '{maxExtraCostShare}', 0.6),
                              (v_ev ->> 'extra_cost_share')::double precision + (v_fr ->> 'extra_cost_share')::double precision),
    'friction', v_fr);
end;
$$;

-- Average revenue per operating hour of the last 24 hours
create or replace function public.macro_ref_revenue(p_company uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(round(avg(h.revenue_cents))::bigint, 0)
    from (select x.revenue_cents from public.player_company_hours x where x.company_id = p_company
           order by x.hour_start desc limit 24) h;
$$;

-- costUnitCents (copied from 0700), sizeUnitCents: above the event pivot at least unitRevenueHours of the hourly
-- revenue; the crisis_manager discount stays
create or replace function public.company_event_unit_cents(p_company uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select y.u - public.apply_bps(y.u, public.company_upgrade_bps(p_company, 'crisis_manager'))
    from (select greatest(public.cfg_num(c, '{costUnit,minUnitCents}', 20000)::bigint,
                          round(public.company_fixed_cost_cents(pc.tier, pc.expansion_level)::numeric
                                * public.cfg_num(c, '{costUnit,unitShareOfFixed}', 0.5)::numeric)::bigint,
                          case when public.macro_size_decades(public.company_worth_cents(p_company)) > 0
                               then round(public.macro_ref_revenue(p_company)::numeric
                                          * public.cfg_num(public.macro_cfg(), '{events,unitRevenueHours}', 0.25)::numeric)::bigint
                               else 0 end) as u
            from public.player_companies pc, (select public.company_events_cfg() as c) x
           where pc.company_id = p_company) y;
$$;

-- ---------------------------------------------------------------------------
-- F. The daily roll (copied from m4h) with size, country and lobby
-- ---------------------------------------------------------------------------
create or replace function public.company_event_roll(p_company uuid, p_now timestamptz default null, p_u double precision[] default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := coalesce(p_now, public.game_now());
  v_cfg    jsonb := public.company_events_cfg();
  m        jsonb := public.macro_cfg();
  v_day    date := (coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date;
  v_u      double precision[] := coalesce(p_u, array[random(), random(), random(), random()]);
  c        public.companies;
  v_last   timestamptz;
  v_arch   jsonb;
  v_id     uuid;
  v_worth  bigint;
  v_dec    double precision;
  v_chance double precision;
  v_share  double precision;
  v_sev    double precision;
  v_lobby  integer;
begin
  if jsonb_typeof(v_cfg -> 'archetypes') is distinct from 'array'
     or not exists (select 1 from public.player_companies pc where pc.company_id = p_company and pc.status = 'active') then
    return null;
  end if;
  insert into public.company_event_rolls (company_id, berlin_day, rolled_at) values (p_company, v_day, v_now)
  on conflict (company_id, berlin_day) do nothing;
  if not found then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  select max(ev.started_at) into v_last from public.player_company_events ev where ev.company_id = p_company;
  -- ADR-209: sizedChancePerDay, sizedChanceShare, sizedSeverityUniform
  v_worth := coalesce(public.company_worth_cents(p_company), 0);
  v_dec := public.macro_size_decades(v_worth);
  v_chance := public.cfg_num(v_cfg, '{chancePerDay}', 0.6);
  v_share := public.cfg_num(v_cfg, '{chanceShare}', 0.4);
  v_sev := v_u[4];
  if v_dec > 0 then
    v_chance := greatest(v_chance, least(public.cfg_num(m, '{events,maxChancePerDay}', 0.95),
                                         v_chance + public.cfg_num(m, '{events,chancePerDayPerDecade}', 0.2) * v_dec));
    v_share := least(v_share, greatest(public.cfg_num(m, '{events,minChanceShare}', 0.15),
                                       v_share - public.cfg_num(m, '{events,chanceShareCutPerDecade}', 0.08) * v_dec));
    v_sev := 1 - power(1 - least(1, greatest(0, v_sev)), 1 + public.cfg_num(m, '{events,severityPowerPerDecade}', 0.6) * v_dec);
  end if;
  if exists (select 1 from public.player_company_events ev where ev.company_id = p_company and ev.status not in ('over', 'expired'))
     or extract(epoch from (v_now - c.founded_at)) / 3600 < public.cfg_num(v_cfg, '{minAgeHours}', 6)
     or (v_last is not null and extract(epoch from (v_now - v_last)) / 3600 < public.cfg_num(v_cfg, '{minGapHours}', 22))
     or v_u[1] >= v_chance then
    return null;
  end if;
  select pc.lobby_level into v_lobby from public.player_companies pc where pc.company_id = p_company;
  v_arch := public.company_event_pick_sized(v_u[3], c.sector_key, case when v_u[2] < v_share then 'chance' else 'crisis' end,
                                            v_worth, public.macro_company_country(p_company), v_lobby);
  if v_arch is null then
    return null;
  end if;
  v_id := public.company_event_start(p_company, v_arch ->> 'key', public.company_event_severity(v_sev), v_now);
  update public.company_event_rolls set event_id = v_id where company_id = p_company and berlin_day = v_day;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Taxes: progressive brackets, exponential advisor
-- ---------------------------------------------------------------------------
-- advisorWageCents: max(minWage, rate × reference revenue), rate × growthPerDecade per tenfold revenue above the pivot
create or replace function public.listed_advisor_wage(p_ref bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(public.cfg_num(a, '{minWageCentsPerHour}', 6000)::bigint,
                  round(greatest(0, coalesce(p_ref, 0))::numeric
                        * (case when coalesce(p_ref, 0) <= public.cfg_num(a, '{pivotCentsPerHour}', 100000)
                                then public.cfg_num(a, '{revenueBps}', 150)
                                else least(public.cfg_num(a, '{maxRevenueBps}', 3000),
                                           public.cfg_num(a, '{revenueBps}', 150)
                                           * power(public.cfg_num(a, '{growthPerDecade}', 2.4),
                                                   log(p_ref::numeric / public.cfg_num(a, '{pivotCentsPerHour}', 100000)::numeric)::double precision)) end)::numeric
                        / 10000)::bigint)
    from (select coalesce(public.listed_cfg() #> '{taxes,advisor}', '{}'::jsonb) as a) x;
$$;

-- progressiveTaxCents: rate on all, extraBps on the part above each bracket (per day, scaled to the period), rounded down
create or replace function public.company_tax_progressive_cents(p_taxable bigint, p_rate integer, p_hours double precision)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select floor((greatest(0, coalesce(p_taxable, 0))::numeric * coalesce(p_rate, 0)
                + coalesce((select sum(greatest(0, greatest(0, coalesce(p_taxable, 0))::numeric
                                                   - (b ->> 'fromCentsPerDay')::numeric * (greatest(1, coalesce(p_hours, 24)) / 24.0)::numeric)
                                       * (b ->> 'extraBps')::numeric)
                              from jsonb_array_elements(coalesce(public.listed_cfg() #> '{taxes,brackets}', '[]'::jsonb)) b), 0))
               / 10000)::bigint;
$$;

-- The base rate: the world map's blended country rate when present (ADR-208), else the listed rate; research on top
create or replace function public.macro_tax_rate_bps(p_company uuid)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  -- a company without a headquarters (world_tax_rate_bps null) keeps the normal rate
  if to_regprocedure('public.world_tax_rate_bps(uuid)') is not null and public.world_tax_rate_bps(p_company) is not null then
    return greatest(public.cfg_num(public.listed_cfg(), '{taxes,minRateBps}', 800),
                    public.world_tax_rate_bps(p_company) + public.cfg_num(public.listed_effects(p_company), '{taxRateBps}', 0))::integer;
  end if;
  return public.listed_tax_rate_bps(p_company);
end;
$$;

-- The open bookkeeping period as the founder sees it (copied from 5410): the estimate uses the brackets
create or replace function public.listed_books_preview(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.listed_cfg();
  l       public.listed_companies;
  s       jsonb;
  v_rev   bigint;
  v_costs bigint;
  v_hours double precision;
  v_today date := (now() at time zone 'Europe/Berlin')::date;
  v_done  boolean;
  v_rate  integer := public.macro_tax_rate_bps(p_company);
begin
  select * into l from public.listed_companies where company_id = p_company;
  s := public.listed_period_sums(p_company, l.books_until, now());
  v_rev := (s ->> 'revenue_cents')::bigint;
  v_costs := (s ->> 'costs_cents')::bigint;
  v_hours := extract(epoch from (now() - l.books_until)) / 3600.0;
  v_done := l.books_day is not null and l.books_day >= v_today;
  return jsonb_build_object(
    'period_start', l.books_until,
    'revenue_cents', v_rev,
    'costs_cents', v_costs,
    'profit_cents', v_rev - v_costs,
    'by_category', s -> 'by_category',
    'loss_carry_cents', l.loss_carry_cents,
    'rate_bps', v_rate,
    'estimated_tax_cents', public.company_tax_progressive_cents(greatest(0, v_rev - v_costs - l.loss_carry_cents), v_rate, v_hours),
    'brackets', coalesce(cfg #> '{taxes,brackets}', '[]'::jsonb),
    'receipts', (select coalesce(jsonb_agg(r - 'category' order by (r ->> 'id')::integer), '[]'::jsonb)
                   from jsonb_array_elements(public.listed_books_receipts(p_company, l.books_until)) r),
    'receipt_categories', coalesce(cfg #> '{taxes,receiptCategories}', '[]'::jsonb),
    'can_close', v_rev > 0 and not v_done,
    'done_today', v_done,
    'hours_open', round(v_hours::numeric, 2),
    'stage', case when v_rev <= 0 then 'none'
                  when v_hours >= public.cfg_num(cfg, '{taxes,estimateAfterHours}', 60) then 'estimate'
                  when v_hours >= public.cfg_num(cfg, '{taxes,lateFeeAfterHours}', 42) then 'late'
                  when v_hours >= public.cfg_num(cfg, '{taxes,reminderAfterHours}', 30) then 'reminder'
                  else 'open' end,
    'reminder_at', l.books_until + make_interval(secs => public.cfg_num(cfg, '{taxes,reminderAfterHours}', 30) * 3600),
    'late_fee_at', l.books_until + make_interval(secs => public.cfg_num(cfg, '{taxes,lateFeeAfterHours}', 42) * 3600),
    'estimate_at', l.books_until + make_interval(secs => public.cfg_num(cfg, '{taxes,estimateAfterHours}', 60) * 3600),
    'streak', l.books_streak,
    'last_day', l.books_day);
end;
$$;

-- Closes the open period (copied from 5410): the gross tax with the progressive brackets; rate_bps stores the
-- effective rate of the period
create or replace function public.listed_books_do(p_company uuid, p_by text, p_correct integer)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.listed_cfg();
  l        public.listed_companies;
  s        jsonb;
  v_rev    bigint;
  v_costs  bigint;
  v_profit bigint;
  v_rate   integer := public.macro_tax_rate_bps(p_company);
  v_hours  double precision;
  v_carry  bigint;
  v_used   bigint := 0;
  v_tax_on bigint := 0;
  v_gross  bigint := 0;
  v_disc   bigint := 0;
  v_tax    bigint := 0;
  v_pen    bigint := 0;
  v_bps    integer;
  v_today  date := (now() at time zone 'Europe/Berlin')::date;
  v_streak integer;
  v_id     bigint;
  v_owner  uuid;
begin
  select * into l from public.listed_companies where company_id = p_company for update;
  if l.company_id is null then
    return null;
  end if;
  s := public.listed_period_sums(p_company, l.books_until, now());
  v_rev := (s ->> 'revenue_cents')::bigint;
  v_costs := (s ->> 'costs_cents')::bigint;
  v_profit := v_rev - v_costs;
  v_carry := l.loss_carry_cents;
  v_hours := extract(epoch from (now() - l.books_until)) / 3600.0;
  if p_by = 'finanzamt' then
    -- estimateTax: at least a margin on the revenue, no loss carried, a surcharge on the tax
    v_tax_on := greatest(v_profit, (v_rev * public.cfg_num(cfg, '{taxes,estimate,marginBps}', 2500)::bigint) / 10000, 0);
    v_tax := public.company_tax_progressive_cents(v_tax_on, v_rate, v_hours);
    v_pen := (v_tax * public.cfg_num(cfg, '{taxes,estimate,surchargeBps}', 2500)::bigint) / 10000;
    v_gross := v_tax;
  elsif v_profit <= 0 then
    v_carry := v_carry - v_profit;
  else
    -- booksTax: the carried loss first, the tax rounded down (with brackets), the discount off the tax
    v_used := least(v_carry, v_profit);
    v_tax_on := v_profit - v_used;
    v_carry := v_carry - v_used;
    v_gross := public.company_tax_progressive_cents(v_tax_on, v_rate, v_hours);
    v_bps := case when p_by = 'advisor' then public.cfg_num(cfg, '{taxes,advisor,discountBps}', 800)::integer
                  when coalesce(p_correct, 0) >= public.cfg_num(cfg, '{taxes,check,receipts}', 3)
                  then public.cfg_num(cfg, '{taxes,check,discountBps}', 500)::integer else 0 end;
    v_disc := (v_gross * v_bps) / 10000;
    v_tax := v_gross - v_disc;
  end if;
  if v_tax_on > 0 then
    v_rate := greatest(v_rate, round(v_gross::numeric * 10000 / v_tax_on)::integer);
  end if;
  insert into public.company_tax_periods (company_id, kind, period_start, period_end, revenue_cents, costs_cents, profit_cents,
                                          loss_used_cents, taxable_cents, rate_bps, discount_cents, tax_cents, penalty_cents, status,
                                          closed_by, check_correct, due_at, paid_at)
  values (p_company, 'books', l.books_until, now(), v_rev, v_costs, v_profit, v_used, v_tax_on, v_rate, v_disc, v_tax, v_pen,
          case when v_tax + v_pen = 0 then 'paid' else 'due' end, p_by, p_correct,
          now() + make_interval(secs => public.cfg_num(cfg, '{taxes,payWithinHours}', 24) * 3600),
          case when v_tax + v_pen = 0 then now() end)
  returning id into v_id;
  v_streak := case when p_by = 'finanzamt' then 0
                   when l.books_day = v_today then greatest(1, l.books_streak)
                   when l.books_day = v_today - 1 then l.books_streak + 1 else 1 end;
  update public.listed_companies
     set books_until = now(), books_day = v_today, books_stage = 0, loss_carry_cents = v_carry, books_streak = v_streak
   where company_id = p_company;
  if p_by <> 'finanzamt' then
    select pc.founder_id into v_owner from public.player_companies pc where pc.company_id = p_company;
    perform public.mission_event(v_owner, 'books_done', 1, v_id::text);
    perform public.mission_event(v_owner, 'books_streak', v_streak, v_id::text);
  end if;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- H. RPCs: risks overview, insurance
-- ---------------------------------------------------------------------------
create or replace function public.company_risks_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  m        jsonb := public.macro_cfg();
  ce       jsonb := public.company_events_cfg();
  pc       public.player_companies;
  c        public.companies;
  v_worth  bigint;
  v_dec    double precision;
  v_chance double precision;
  v_share  double precision;
  v_country jsonb;
  v_total  double precision;
  v_fr     jsonb;
  v_ref    bigint;
  v_levels jsonb;
  v_exp    jsonb;
  v_next   jsonb;
  v_wait   timestamptz;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into c from public.companies where id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  v_worth := coalesce(public.company_worth_cents(p_company), 0);
  v_dec := public.macro_size_decades(v_worth);
  v_chance := public.cfg_num(ce, '{chancePerDay}', 0.6);
  v_share := public.cfg_num(ce, '{chanceShare}', 0.4);
  if v_dec > 0 then
    v_chance := greatest(v_chance, least(public.cfg_num(m, '{events,maxChancePerDay}', 0.95),
                                         v_chance + public.cfg_num(m, '{events,chancePerDayPerDecade}', 0.2) * v_dec));
    v_share := least(v_share, greatest(public.cfg_num(m, '{events,minChanceShare}', 0.15),
                                       v_share - public.cfg_num(m, '{events,chanceShareCutPerDecade}', 0.08) * v_dec));
  end if;
  v_country := public.macro_company_country(p_company);
  select coalesce(sum(public.macro_weight(t.x, v_worth, v_country, pc.lobby_level)), 0) into v_total
    from jsonb_array_elements(coalesce(ce -> 'archetypes', '[]'::jsonb)) t(x)
   where t.x ->> 'polarity' = 'crisis'
     and (jsonb_typeof(t.x -> 'sectors') is distinct from 'array' or t.x -> 'sectors' ? c.sector_key);
  -- daily probability of every external archetype (bps), most likely first
  select coalesce(jsonb_agg(jsonb_build_object('archetype', q.k, 'bps', q.bps, 'insurable', q.ins, 'risk', q.risk)
                            order by q.bps desc, q.k), '[]'::jsonb)
    into v_exp
    from (select t.x ->> 'key' as k, coalesce((t.x ->> 'insurable')::boolean, false) as ins, t.x ->> 'risk' as risk,
                 round(case when v_total > 0 then v_chance * (1 - v_share) * public.macro_weight(t.x, v_worth, v_country, pc.lobby_level) / v_total
                            else 0 end * 10000)::integer as bps
            from jsonb_array_elements(coalesce(ce -> 'archetypes', '[]'::jsonb)) t(x)
           where coalesce((t.x ->> 'external')::boolean, false)
             and (jsonb_typeof(t.x -> 'sectors') is distinct from 'array' or t.x -> 'sectors' ? c.sector_key)) q
   where q.bps > 0;
  -- external events still to come with growth
  select coalesce(jsonb_agg(jsonb_build_object('archetype', t.x ->> 'key', 'from_cents', (t.x ->> 'minWorthCents')::bigint)
                            order by (t.x ->> 'minWorthCents')::bigint, t.x ->> 'key'), '[]'::jsonb)
    into v_next
    from jsonb_array_elements(coalesce(ce -> 'archetypes', '[]'::jsonb)) t(x)
   where coalesce((t.x ->> 'external')::boolean, false) and coalesce((t.x ->> 'minWorthCents')::bigint, 0) > v_worth;
  v_fr := public.macro_friction(v_worth, 0);
  select coalesce(round(avg(h.revenue_cents))::bigint, 0) into v_ref
    from (select x.revenue_cents from public.player_company_hours x where x.company_id = p_company
           order by x.hour_start desc limit 24) h;
  select coalesce(jsonb_agg(jsonb_build_object('level', (o - 1)::integer, 'key', lv ->> 'key',
                                               'coverage_bps', round(public.cfg_num(lv, '{coverage}', 0) * 10000)::integer,
                                               'premium_bps', public.cfg_num(lv, '{premiumBps}', 0)::integer,
                                               'premium_cents_per_hour', (v_ref * public.cfg_num(lv, '{premiumBps}', 0)::bigint) / 10000)
                            order by o), '[]'::jsonb)
    into v_levels
    from jsonb_array_elements(coalesce(m #> '{insurance,levels}', '[]'::jsonb)) with ordinality t(lv, o);
  v_wait := case when pc.insurance_changed_at is null then null
                 else pc.insurance_changed_at + make_interval(secs => public.cfg_num(m, '{insurance,changeWaitHours}', 12) * 3600) end;
  return jsonb_build_object(
    'company_id', p_company,
    'worth_cents', v_worth,
    'decades', round(v_dec::numeric, 3)::double precision,
    'event_pivot_cents', public.cfg_num(m, '{events,worthPivotCents}', 2000000000)::bigint,
    'friction_pivot_cents', public.cfg_num(m, '{friction,worthPivotCents}', 3000000000)::bigint,
    'saturation_bps', round((v_fr ->> 'demand_factor')::numeric * 10000)::integer,
    'overhead_bps', round((v_fr ->> 'extra_cost_share')::numeric * 10000)::integer,
    'chance_per_day_bps', round(v_chance * 10000)::integer,
    'crisis_share_bps', round((1 - v_share) * 10000)::integer,
    'unit_cents', public.company_event_unit_cents(p_company),
    'exposure', v_exp,
    'upcoming', v_next,
    'ref_revenue_cents', v_ref,
    'insurance', jsonb_build_object(
      'level', pc.insurance_level,
      'coverage_bps', round(coalesce(public.macro_coverage(p_company), 0) * 10000)::integer,
      'changed_at', pc.insurance_changed_at,
      'full_from', case when v_wait is not null and v_wait > public.game_now() then v_wait end,
      'levels', v_levels),
    'lobby', jsonb_build_object(
      'level', pc.lobby_level,
      'max', public.cfg_num(m, '{lobby,maxLevel}', 5)::integer,
      'bonus_bps', (least(pc.lobby_level, public.cfg_num(m, '{lobby,maxLevel}', 5)) * public.cfg_num(m, '{lobby,successBpsPerLevel}', 350))::integer,
      'political_cut_bps', round(least(1, least(pc.lobby_level, public.cfg_num(m, '{lobby,maxLevel}', 5))
                                          * public.cfg_num(m, '{lobby,politicalCutPerLevel}', 0.12)) * 10000)::integer,
      'leader', coalesce(public.company_is_market_leader(p_company), false)),
    'country', case when v_country is null then null
                    else jsonb_build_object('key', public.company_country(p_company), 'name', v_country ->> 'name') end);
end;
$$;

create or replace function public.get_company_risks()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.company_risks_json(public.require_own_company());
end;
$$;
comment on function public.get_company_risks() is
  'RPC (founder): the risks of the own company (ADR-209): value, size friction, daily event chance, exposure to every '
  'external event, insurance and lobby.';

create or replace function public.set_company_insurance(p_request_id uuid, p_level integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_max     integer;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  v_max := jsonb_array_length(coalesce(public.macro_cfg() #> '{insurance,levels}', '[{}]'::jsonb)) - 1;
  if p_request_id is null or p_level is null or p_level < 0 or p_level > v_max then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_insurance');
  if v_replay is not null then
    return v_replay;
  end if;
  update public.player_companies
     -- the level that covers right now (a change inside the wait keeps the lower one)
     set insurance_prev_level = case when insurance_level = p_level then insurance_prev_level
                                     when insurance_changed_at is null
                                          or insurance_changed_at + make_interval(secs => public.cfg_num(public.macro_cfg(), '{insurance,changeWaitHours}', 12) * 3600)
                                             <= public.game_now()
                                     then insurance_level
                                     else least(insurance_level, insurance_prev_level) end,
         insurance_changed_at = case when insurance_level = p_level then insurance_changed_at else public.game_now() end,
         insurance_level = p_level
   where company_id = v_company;
  return public.request_complete(v_player, p_request_id, public.company_risks_json(v_company));
end;
$$;
comment on function public.set_company_insurance(uuid, integer) is
  'RPC (founder): insurance level against disasters and cyber attacks (ADR-209). Premium every hour as a share of the '
  'own revenue; a higher level covers events only after insurance.changeWaitHours.';

-- ---------------------------------------------------------------------------
-- I. Grants
-- ---------------------------------------------------------------------------
revoke all on function public.macro_cfg(), public.macro_size_decades(bigint), public.macro_friction(bigint, integer),
  public.macro_country_factor(jsonb, jsonb), public.macro_weight(jsonb, bigint, jsonb, integer),
  public.macro_company_country(uuid), public.company_event_pick_sized(double precision, text, text, bigint, jsonb, integer),
  public.macro_coverage(uuid, timestamptz), public.macro_event_snapshot_trg(), public.macro_lobby_win_trg(),
  public.company_tax_progressive_cents(bigint, integer, double precision), public.macro_tax_rate_bps(uuid),
  public.company_risks_json(uuid), public.macro_ref_revenue(uuid)
  from public, anon, authenticated;
revoke all on function public.get_company_risks(), public.set_company_insurance(uuid, integer) from public, anon;
grant execute on function public.get_company_risks(), public.set_company_insurance(uuid, integer) to authenticated;

-- ===== supabase/migrations/20261204010200_talents_after_clone.sql =====
-- =============================================================================
-- NEXA · 10200 · Talente im Organigramm, nach Klon und Jobs (ADR-199, ADR-206)
-- =============================================================================
-- Talents lead their Stelle and stand above the AI workers in the hierarchy. get_company_org (full copy of the latest
-- definition from 20261204000100_company_tasks.sql, unchanged otherwise) now also returns the talents of the company:
-- Mit-Geschäftsführer first, then by tier (Legende first), then by Stelle. Runs after the clone/jobs migrations
-- (9800/9810); none of the team or job functions they rewrote carry talent logic, so nothing else is re-applied.
-- Idempotent (create or replace).

create or replace function public.get_company_org(p_company_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  pc       public.player_companies;
  c        public.companies;
begin
  select * into pc from public.player_companies where company_id = p_company_id and status = 'active';
  if pc.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  select * into c from public.companies where id = p_company_id;
  -- open to every player (ADR-125): the org chart shows who works where, nothing more
  return jsonb_build_object(
    'company', jsonb_build_object('id', c.id, 'name', c.name, 'tier', pc.tier),
    'founder', (select jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key,
                                          'is_me', p.id = v_player)
                  from public.profiles p where p.id = pc.founder_id),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'avatar_key', p.avatar_key, 'tier', j.tier,
                                          'title', coalesce(j.title, j.title_key), 'since', j.started_at,
                                          'is_me', j.player_id = v_player,
                                          'supervisor', (select s.nickname from public.profiles s where s.id = j.supervisor_id))
                       order by case j.tier::text when 'c_level' then 5 when 'team_lead' then 4 when 'senior' then 3
                                                  when 'junior' then 2 else 1 end desc, j.started_at, p.nickname)
        from public.player_jobs j join public.profiles p on p.id = j.player_id
       where j.company_id = p_company_id and j.status = 'active'), '[]'::jsonb),
    -- Talente (ADR-199): above the AI workers; public facts only (no wage, no satisfaction)
    'talents', coalesce((
      select jsonb_agg(jsonb_build_object('key', t.talent_key, 'first_name', t.first_name, 'last_name', t.last_name,
                                          'avatar_key', t.avatar_key, 'role', t.role_key, 'tier', t.tier,
                                          'is_coceo', t.is_coceo, 'since', t.hired_at)
                       order by t.is_coceo desc, t.tier desc, t.role_key, t.talent_key)
        from public.talents t
       where t.company_id = p_company_id), '[]'::jsonb),
    'ai_workers', pc.ai_workers,
    'ai_worker_skills', to_jsonb(coalesce(pc.ai_worker_skills, '{}'::text[])));
end;
$$;

-- ===== supabase/migrations/20261204010300_hour_effect_talents_world.sql =====
-- =============================================================================
-- Talente and Weltkarte both in the hour terms (ADR-199, ADR-208)
-- =============================================================================
-- 010010 (Weltkarte) redefined listed_hour_effect from the 8300 version and so dropped the Talente factor that 8900
-- added. This is the 010010 definition with the Talente block of 8900 put back, in the same order as before (skills,
-- Talente, Weltkarte).

create or replace function public.listed_hour_effect(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  l    public.listed_companies;
  v_df double precision := 1;
  v_r  jsonb;
  v_sk jsonb;
  v_w  jsonb;
  v_tl jsonb;
begin
  l := public.listed_ensure(p_company);
  if l.company_id is null then
    begin
      v_df := public.company_reputation_demand_factor(
                (select pc.reputation from public.player_companies pc where pc.company_id = p_company));
    exception when others then
      v_df := 1;
    end;
    v_r := jsonb_build_object('awareness_add', 0, 'quality_add', 0, 'demand_factor', coalesce(v_df, 1), 'capacity_factor', 1,
                              'cogs_factor', 1, 'fixed_factor', 1, 'listed', false);
  else
    v_r := public.listed_hour_effect_calc(public.listed_effects(p_company), l.satisfaction, l.reputation)
           || jsonb_build_object('listed', true);
  end if;
  -- ADR-194: Fertigkeiten; a failure never stops the close
  begin
    v_sk := public.company_skills_hour_effect(p_company, p_hour_start);
    v_r := v_r || jsonb_build_object(
      'demand_factor', (v_r ->> 'demand_factor')::double precision * (v_sk ->> 'demand_factor')::double precision,
      'capacity_factor', (v_r ->> 'capacity_factor')::double precision * (v_sk ->> 'capacity_factor')::double precision,
      'cogs_factor', (v_r ->> 'cogs_factor')::double precision * (v_sk ->> 'cogs_factor')::double precision,
      'fixed_factor', (v_r ->> 'fixed_factor')::double precision * (v_sk ->> 'fixed_factor')::double precision,
      'quality_add', (v_r ->> 'quality_add')::double precision + (v_sk ->> 'quality_add')::double precision,
      'skills', v_sk);
  exception when others then
    null;
  end;
  -- ADR-199: Talente of the filled Stellen; a failure never stops the close
  begin
    v_tl := public.talents_hour_effect(p_company);
    v_r := v_r || jsonb_build_object(
      'demand_factor', (v_r ->> 'demand_factor')::double precision * (v_tl ->> 'demand_factor')::double precision,
      'capacity_factor', (v_r ->> 'capacity_factor')::double precision * (v_tl ->> 'capacity_factor')::double precision,
      'cogs_factor', (v_r ->> 'cogs_factor')::double precision * (v_tl ->> 'cogs_factor')::double precision,
      'fixed_factor', (v_r ->> 'fixed_factor')::double precision * (v_tl ->> 'fixed_factor')::double precision,
      'quality_add', (v_r ->> 'quality_add')::double precision + (v_tl ->> 'quality_add')::double precision,
      'talents', v_tl);
  exception when others then
    null;
  end;
  -- ADR-208: Weltkarte (country of the HQ, subsidiaries, prestige); a failure never stops the close
  begin
    v_w := public.world_hour_effect(p_company, p_hour_start);
    if coalesce((v_w ->> 'placed')::boolean, false) then
      v_r := v_r || jsonb_build_object(
        'demand_factor', (v_r ->> 'demand_factor')::double precision * (v_w ->> 'demand_factor')::double precision,
        'cogs_factor', (v_r ->> 'cogs_factor')::double precision * (v_w ->> 'cogs_factor')::double precision,
        'fixed_factor', (v_r ->> 'fixed_factor')::double precision * (v_w ->> 'fixed_factor')::double precision,
        'world', v_w);
    end if;
  exception when others then
    perform public.company_close_warn(p_company, 'world_effect', sqlerrm);
  end;
  return v_r;
end;
$$;


-- ===== supabase/migrations/20261204010400_news_show_fresh.sql =====
-- =============================================================================
-- NEXA · 10400 · NEXA Nachrichten, season three: new content for Mr. Doodle Dangle and the chat (ADR-210)
-- =============================================================================
-- * news_show_topic_cands_fresh(): what the new topics could tell (game_config newsShow.topics.list, texts and moods
--   from src/config/news-topics-fresh.ts): new headquarters, upgrades, market leaders, location fees and
--   subsidiaries (Weltkarte, ADR-208), events from outside that hit a player company and the ones it overcame
--   (ADR-209), star hires, poaching, quits, co-CEOs and the best free talent (ADR-199), clones with a job (ADR-206),
--   climbers of the rich list and of the company list (ADR-203), the Pleite der Woche, Black Labels, Pack Battle
--   Twist winners and pack marathons, big Festgeld deposits and their interest (ADR-201), login streaks, company
--   skills, redrawn logos (ADR-200) and the Wetter auf der Weltkarte. The Börsen-Orakel needs no data.
-- * news_show_topics(): the latest full definition (5700) plus the call of those candidates and a segue in front of
--   a topic now and then (news_show_segue()).
-- * news_show_pick(): the latest full definition (2000); a frame or reason that aired in the last
--   newsShow.fresh.noRepeatShows shows only comes back when nothing else is left (key "f:<kind>:<frame>" is new).
-- * news_show_fresh_chat(), trigger news_shows_fresh_chat: when a show goes on air the made-up viewers react to each
--   segment (lines by topic or kind), now and then a poll with votes, an emote storm after a big pull. Real players'
--   chat is untouched. No chat line or poll repeats within noRepeatShows shows while the pool has others.
-- Idempotent: runs unchanged as supabase/updates/20261204010400_news_show_fresh.sql.

-- ---------------------------------------------------------------------------
-- What "recent" means: everything used after the build of the N-th latest show before this one
-- ---------------------------------------------------------------------------
create or replace function public.news_show_fresh_cutoff(p_exclude bigint default null)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select s.created_at
       from public.news_shows s
      where s.id is distinct from p_exclude
      order by s.airs_at desc
     offset greatest(coalesce((public.news_show_cfg() #>> '{fresh,noRepeatShows}')::integer, 0), 1) - 1
      limit 1),
    '-infinity'::timestamptz);
$$;
comment on function public.news_show_fresh_cutoff(bigint) is
  'Internal (ADR-210): keys of news_show_used newer than this were used in the last newsShow.fresh.noRepeatShows shows.';

-- ---------------------------------------------------------------------------
-- news_show_pick(): latest full definition (20261204002000), plus the rule of ADR-210
-- ---------------------------------------------------------------------------
-- A frame and a reason for a kind: first a pair whose frame and reason did not air in the last shows, then the
-- combination used longest ago, among those the reason used longest ago, then by chance (pickScript); remembers the
-- pick. -> {"headline", "text"} with {reason} filled in
create or replace function public.news_show_pick(p_kind text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  kit   jsonb := public.news_show_cfg() -> 'texts' -> p_kind;
  v_cut timestamptz := public.news_show_fresh_cutoff(null);
  r     record;
begin
  select f.ord - 1 as f, x.ord - 1 as r, f.val ->> 'headline' as headline, f.val ->> 'text' as body, x.val as reason
    into r
    from jsonb_array_elements(coalesce(kit -> 'frames', '[]'::jsonb)) with ordinality f(val, ord)
   cross join jsonb_array_elements_text(coalesce(kit -> 'reasons', '[]'::jsonb)) with ordinality x(val, ord)
    left join public.news_show_used u on u.key = p_kind || ':' || (f.ord - 1) || ':' || (x.ord - 1)
    left join public.news_show_used ur on ur.key = 'r:' || p_kind || ':' || (x.ord - 1)
    left join public.news_show_used uf on uf.key = 'f:' || p_kind || ':' || (f.ord - 1)
   order by coalesce(uf.used_at > v_cut, false)::integer + coalesce(ur.used_at > v_cut, false)::integer,
            u.used_at nulls first, ur.used_at nulls first, random()
   limit 1;
  if r.headline is null then
    return null;
  end if;
  insert into public.news_show_used (key, used_at) values (p_kind || ':' || r.f || ':' || r.r, clock_timestamp())
  on conflict (key) do update set used_at = excluded.used_at;
  insert into public.news_show_used (key, used_at) values ('r:' || p_kind || ':' || r.r, clock_timestamp())
  on conflict (key) do update set used_at = excluded.used_at;
  insert into public.news_show_used (key, used_at) values ('f:' || p_kind || ':' || r.f, clock_timestamp())
  on conflict (key) do update set used_at = excluded.used_at;
  return jsonb_build_object('headline', r.headline, 'text', replace(r.body, '{reason}', r.reason));
end;
$$;

-- ---------------------------------------------------------------------------
-- A segue in front of a topic now and then (newsShow.fresh.transitions), not one of the last shows
-- ---------------------------------------------------------------------------
create or replace function public.news_show_segue(p_seg jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  fc    jsonb := public.news_show_cfg() -> 'fresh';
  v_cut timestamptz := public.news_show_fresh_cutoff(null);
  v_t   text;
begin
  if p_seg is null or fc is null or random() * 10000 >= coalesce((fc ->> 'transitionChanceBps')::integer, 0) then
    return p_seg;
  end if;
  select t into v_t
    from jsonb_array_elements_text(coalesce(fc -> 'transitions', '[]'::jsonb)) t
    left join public.news_show_used u on u.key = 't:' || md5(t)
   where u.used_at is null or u.used_at <= v_cut
   order by u.used_at nulls first, random()
   limit 1;
  if v_t is null then
    return p_seg;
  end if;
  insert into public.news_show_used (key, used_at) values ('t:' || md5(v_t), clock_timestamp())
  on conflict (key) do update set used_at = excluded.used_at;
  return jsonb_set(p_seg, '{text}', to_jsonb(v_t || ' ' || (p_seg ->> 'text')));
end;
$$;
comment on function public.news_show_segue(jsonb) is
  'Internal (ADR-210): puts one of newsShow.fresh.transitions in front of a segment text (transitionChanceBps).';

-- ---------------------------------------------------------------------------
-- The candidates of the new topics: at most a few per topic, read from tables that exist anyway
-- ---------------------------------------------------------------------------
create or replace function public.news_show_topic_cands_fresh(p_now timestamptz, p_win interval)
returns table (topic text, player_id uuid, vals jsonb, ukey text, score double precision)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.news_show_cfg();
  fc      jsonb := coalesce(public.news_show_cfg() -> 'fresh', '{}'::jsonb);
  ff      jsonb := coalesce(public.news_show_cfg() #> '{fresh,facts}', '{}'::jsonb);
  v_day   text := (p_now at time zone 'Europe/Berlin')::date::text;
  v_today date := (p_now at time zone 'Europe/Berlin')::date;
  v_names jsonb := coalesce((select g.value from public.game_config g where g.key = 'nexamon_names'), '{}'::jsonb);
  v_home  text := coalesce(public.news_show_cfg() #>> '{fresh,homeCountry}', 'Nexa-Stadt');
  v_ext   text[];
  v_new   timestamptz;
  v_old   timestamptz;
  v_week  timestamptz;
  v_cnew  timestamptz;
  v_cold  timestamptz;
begin
  if fc = '{}'::jsonb then
    return;
  end if;
  -- the external archetypes (ADR-209)
  select coalesce(array_agg(x ->> 'key'), '{}') into v_ext
    from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) x
   where coalesce((x ->> 'external')::boolean, false);
  -- the rich list and the company list now, a window ago and a week ago
  select max(r.taken_at) into v_new from public.rich_list_snapshots r where r.taken_at <= p_now;
  select max(r.taken_at) into v_old from public.rich_list_snapshots r where r.taken_at <= p_now - p_win;
  select max(r.taken_at) into v_week from public.rich_list_snapshots r
   where r.taken_at <= p_now - make_interval(days => coalesce((ff ->> 'weekDays')::integer, 7));
  select max(r.taken_at) into v_cnew from public.company_rank_snapshots r where r.taken_at <= p_now;
  select max(r.taken_at) into v_cold from public.company_rank_snapshots r where r.taken_at <= p_now - p_win;

  return query
  -- ---- Weltkarte (ADR-208)
  select 'worldHq'::text, pc.founder_id,
         jsonb_build_object('company', co.name, 'country', public.country_cfg(l.country_key) ->> 'name'),
         'fact:hq:' || l.company_id::text || ':' || l.country_key,
         extract(epoch from coalesce(l.moved_at, l.placed_at))::double precision
    from public.company_locations l
    join public.companies co on co.id = l.company_id
    join public.player_companies pc on pc.company_id = l.company_id
   where coalesce(l.moved_at, l.placed_at) between p_now - p_win and p_now
     and public.country_cfg(l.country_key) ->> 'name' is not null
  union all
  select 'worldHqUp', pc.founder_id,
         jsonb_build_object('company', co.name, 'country', public.country_cfg(l.country_key) ->> 'name', 'tier', l.hq_tier),
         'fact:hqup:' || l.company_id::text || ':' || l.hq_tier::text, l.hq_tier::double precision
    from public.company_locations l
    join public.companies co on co.id = l.company_id
    join public.player_companies pc on pc.company_id = l.company_id
   where l.updated_at between p_now - p_win and p_now
     and l.hq_tier >= coalesce((ff ->> 'hqMinTier')::integer, 2)
     and public.country_cfg(l.country_key) ->> 'name' is not null
  union all
  select 'worldLeader', pc.founder_id,
         jsonb_build_object('company', co.name, 'country', public.country_cfg(cl.country_key) ->> 'name'),
         'fact:leader:' || cl.country_key || ':' || cl.leader_company_id::text, random()
    from public.country_lobby cl
    join public.companies co on co.id = cl.leader_company_id
    left join public.player_companies pc on pc.company_id = cl.leader_company_id
   where cl.updated_at between p_now - p_win and p_now
     and public.country_cfg(cl.country_key) ->> 'name' is not null
  union all
  select 'worldFee', pc.founder_id,
         jsonb_build_object('company', co.name, 'country', public.country_cfg(cl.country_key) ->> 'name',
                            'pct', public.news_show_move(cl.fee_bps)),
         'fact:fee:' || cl.country_key || ':' || cl.fee_bps::text || ':' || cl.leader_company_id::text,
         cl.fee_bps::double precision
    from public.country_lobby cl
    join public.companies co on co.id = cl.leader_company_id
    left join public.player_companies pc on pc.company_id = cl.leader_company_id
   where cl.fee_bps > 0 and cl.fee_set_at between p_now - p_win and p_now
     and public.country_cfg(cl.country_key) ->> 'name' is not null
  union all
  select 'worldSub', pc.founder_id,
         jsonb_build_object('company', co.name, 'country', public.country_cfg(s.country_key) ->> 'name',
                            'count', (select count(*) from public.company_subsidiaries s2 where s2.company_id = s.company_id)),
         'fact:sub:' || s.company_id::text || ':' || s.country_key,
         extract(epoch from s.opened_at)::double precision
    from public.company_subsidiaries s
    join public.companies co on co.id = s.company_id
    join public.player_companies pc on pc.company_id = s.company_id
   where s.opened_at between p_now - p_win and p_now
     and public.country_cfg(s.country_key) ->> 'name' is not null
     and (select count(*) from public.company_subsidiaries s2 where s2.company_id = s.company_id)
         >= coalesce((ff ->> 'subsidiaryMin')::integer, 1)
  union all
  (select 'worldWeather', null::uuid, jsonb_build_object('country', x ->> 'name'),
          'fact:weather:' || (x ->> 'key') || ':' || v_day, random()
     from jsonb_array_elements(coalesce(public.world_cfg() -> 'countries', '[]'::jsonb)) x
    where x ->> 'name' is not null
    order by random() limit 1)
  -- ---- Talente (ADR-199) and clones (ADR-206)
  union all
  select case te.kind when 'hired' then 'talentStar' when 'poached' then 'talentPoach' when 'quit' then 'talentQuit'
                      else 'talentCoceo' end,
         pc.founder_id,
         jsonb_strip_nulls(jsonb_build_object(
           'company', co.name, 'talent', te.payload ->> 'name',
           'role', coalesce(fc #>> array['roleNames', te.payload ->> 'role'], te.payload ->> 'role'),
           'rival', te.payload ->> 'to_name')),
         'fact:talent:' || te.id::text,
         coalesce((te.payload ->> 'tier')::double precision, 1)
    from public.talent_events te
    join public.companies co on co.id = te.company_id
    join public.player_companies pc on pc.company_id = te.company_id
   where te.created_at between p_now - p_win and p_now and te.undone_at is null
     and te.payload ->> 'name' is not null
     and (te.kind in ('quit', 'coceo_appointed')
          or (te.kind = 'poached' and te.payload ->> 'to_name' is not null)
          or (te.kind = 'hired' and coalesce((te.payload ->> 'tier')::integer, 0) >= coalesce((ff ->> 'starMinTier')::integer, 2)))
  union all
  (select 'talentMarket', null::uuid,
          jsonb_build_object('talent', t.first_name || ' ' || t.last_name,
                             'role', coalesce(fc #>> array['roleNames', t.role_key], t.role_key),
                             'tier', coalesce(fc #>> array['tierNames', t.tier::text], t.tier::text),
                             'amount', public.format_eur(t.wage_demand_cents)),
          'fact:tmarket:' || t.talent_key || ':' || v_day, t.tier::double precision
     from public.talents t
    where t.company_id is null and t.tier >= coalesce((ff ->> 'starMinTier')::integer, 2)
      and (t.resting_until is null or t.resting_until <= p_now)
    order by t.tier desc, random() limit 1)
  union all
  select 'cloneJob', j.player_id, jsonb_build_object('company', co.name, 'title', j.title),
         'fact:clone:' || j.id::text, extract(epoch from j.started_at)::double precision
    from public.player_jobs j
    join public.companies co on co.id = j.company_id
   where j.is_clone and j.started_at between p_now - p_win and p_now
  -- ---- toplists (ADR-203)
  union all
  select 'rankForbes', a.entity_id, jsonb_build_object('rank', a.rank_all, 'places', b.rank_all - a.rank_all),
         'fact:forbes:' || a.entity_id::text || ':' || v_day, (b.rank_all - a.rank_all)::double precision
    from public.rich_list_snapshots a
    join public.rich_list_snapshots b on b.taken_at = v_old and b.entity_kind = a.entity_kind and b.entity_id = a.entity_id
   where v_old is not null and v_new > v_old and a.taken_at = v_new and a.entity_kind = 'player'
     and b.rank_all - a.rank_all >= coalesce((ff ->> 'rankMinPlaces')::integer, 3)
  union all
  select 'rankCompany', pc.founder_id, jsonb_build_object('company', co.name, 'rank', a.rank_all, 'places', b.rank_all - a.rank_all),
         'fact:crank:' || a.company_id::text || ':' || v_day, (b.rank_all - a.rank_all)::double precision
    from public.company_rank_snapshots a
    join public.company_rank_snapshots b on b.taken_at = v_cold and b.company_id = a.company_id
    join public.companies co on co.id = a.company_id
    left join public.player_companies pc on pc.company_id = a.company_id
   where v_cold is not null and v_cnew > v_cold and a.taken_at = v_cnew
     and b.rank_all - a.rank_all >= coalesce((ff ->> 'rankMinPlaces')::integer, 3)
  union all
  select 'rankWeekLoser', a.entity_id,
         jsonb_build_object('amount', public.format_eur(b.net_worth_cents - a.net_worth_cents),
                            'pct', public.news_show_move(((b.net_worth_cents - a.net_worth_cents) * 10000 / b.net_worth_cents)::integer)),
         'fact:weekloser:' || a.entity_id::text || ':' || to_char(p_now at time zone 'Europe/Berlin', 'IYYY-IW'),
         (b.net_worth_cents - a.net_worth_cents)::double precision
    from public.rich_list_snapshots a
    join public.rich_list_snapshots b on b.taken_at = v_week and b.entity_kind = a.entity_kind and b.entity_id = a.entity_id
   where v_week is not null and v_new > v_week and a.taken_at = v_new and a.entity_kind = 'player'
     and b.net_worth_cents > 0
     and (b.net_worth_cents - a.net_worth_cents) * 10000 / b.net_worth_cents >= coalesce((ff ->> 'weekLossMinBps')::integer, 1000)
  -- ---- Nexamon (ADR-165, ADR-205)
  union all
  select 'cardBlackLabel', c2.owner_id,
         jsonb_build_object('card', coalesce(v_names ->> c2.card_key, c2.card_key),
                            'fee', public.format_eur(coalesce(c2.grading_fee_cents, 0))),
         'fact:nblack:' || c2.id::text, extract(epoch from c2.graded_at)::double precision
    from public.nexamon_copies c2
   where c2.owner_id is not null and c2.grade = 11 and c2.graded_at between p_now - p_win and p_now
  union all
  select 'cardTwist', st.player_id,
         jsonb_build_object('count', b.size,
                            'amount', public.format_eur((select coalesce(sum(coalesce(x.total_cents, 0)), 0)::bigint
                                                           from public.nexamon_battle_seats x where x.battle_id = b.id))),
         'fact:twist:' || b.id::text, extract(epoch from b.ends_at)::double precision
    from public.nexamon_battles b
    join public.nexamon_battle_seats st on st.battle_id = b.id and st.seat = b.winner_seat
   where b.twist and b.status = 'accepted' and b.winner_seat is not null
     and b.ends_at between p_now - p_win and p_now
  union all
  select 'cardSpree', d.player_id, jsonb_build_object('packs', d.n, 'amount', public.format_eur(d.spent)),
         'fact:spree:' || d.player_id::text || ':' || v_day, d.n::double precision
    from (select pk.player_id, count(*) as n, sum(pk.price_cents)::bigint as spent
            from public.nexamon_packs pk
           where pk.opened_at between p_now - p_win and p_now and pk.player_id is not null
           group by pk.player_id) d
   where d.n >= coalesce((ff ->> 'spreeMinPacks')::integer, 10)
  -- ---- Festgeld (ADR-201), streaks, company skills
  union all
  select 'pVault', v.player_id, jsonb_build_object('amount', public.format_eur(v.amount_cents), 'days', v.term_days),
         'fact:vault:' || v.id::text, v.amount_cents::double precision
    from public.vault_deposits v
   where v.created_at between p_now - p_win and p_now and v.status in ('open', 'paid')
     and v.amount_cents >= coalesce((ff ->> 'vaultMinCents')::bigint, 500000)
  union all
  select 'pVaultPaid', v.player_id, jsonb_build_object('amount', public.format_eur(v.interest_cents)),
         'fact:vaultpaid:' || v.id::text, v.interest_cents::double precision
    from public.vault_deposits v
   where v.status = 'paid' and v.closed_at between p_now - p_win and p_now
     and v.interest_cents >= coalesce((ff ->> 'vaultInterestMinCents')::bigint, 5000)
  union all
  select 'pStreak', ls.player_id, jsonb_build_object('days', ls.current_streak),
         'fact:streak:' || ls.player_id::text || ':' || ls.current_streak::text, ls.current_streak::double precision
    from public.login_streaks ls
   where ls.current_streak >= coalesce((ff ->> 'streakMinDays')::integer, 7)
     and ls.current_streak % coalesce((ff ->> 'streakMinDays')::integer, 7) = 0
     and ls.last_login_day >= v_today - 1
  union all
  select 'corpSkill', pc.founder_id,
         jsonb_build_object('company', co.name, 'skill', coalesce(fc #>> array['skillNames', k.skill_key], k.skill_key),
                            'level', k.level),
         'fact:skill:' || k.company_id::text || ':' || k.skill_key || ':' || k.level::text, k.level::double precision
    from public.company_skills k
    join public.companies co on co.id = k.company_id
    join public.player_companies pc on pc.company_id = k.company_id
   where k.ready_at between p_now - p_win and p_now
     and k.level >= coalesce((ff ->> 'skillMinLevel')::integer, 3)
  -- ---- big market events (ADR-214): stock tips with source 'market', when the game has them
  union all
  select 'marketEvent', null::uuid,
         jsonb_build_object('what', t.headline, 'stock', sec.name, 'pct', public.news_show_move(t.move_bps)),
         'fact:market:' || t.id::text, t.move_bps::double precision
    from public.stock_tips t
    join public.securities sec on sec.id = t.security_id
   where to_jsonb(t) ->> 'source' = 'market'
     and t.published_at between p_now - p_win and p_now
     and t.move_bps >= coalesce((ff ->> 'marketMinBps')::integer, 300)
  -- ---- a redrawn logo (ADR-200), when the game has it
  union all
  select 'corpLogo', pc.founder_id,
         jsonb_build_object('company', co.name,
                            'amount', public.format_eur(coalesce((public.config_jsonb('startups') ->> 'logoRedrawCents')::bigint, 0))),
         'fact:logo:' || pc.company_id::text || ':' || extract(epoch from (to_jsonb(pc) ->> 'logo_redrawn_at')::timestamptz)::bigint::text,
         extract(epoch from (to_jsonb(pc) ->> 'logo_redrawn_at')::timestamptz)::double precision
    from public.player_companies pc
    join public.companies co on co.id = pc.company_id
   where (to_jsonb(pc) ->> 'logo_redrawn_at')::timestamptz between p_now - p_win and p_now;
end;
$$;
comment on function public.news_show_topic_cands_fresh(timestamptz, interval) is
  'Internal (ADR-210): candidates of the season-three topics of the news show (topic, player, values, fact key, '
  'score); news_show_topics() draws them like every other topic.';

-- ---------------------------------------------------------------------------
-- Events from outside (ADR-209) get their own segments: every big one that hit a player company, and a follow-up
-- once it is over (newsShow.fresh.events)
-- ---------------------------------------------------------------------------
create or replace function public.news_show_event_response(p_event public.player_company_events, p_phase text)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  ev     jsonb := coalesce(public.news_show_cfg() #> '{fresh,events}', '{}'::jsonb);
  r      jsonb := coalesce(public.news_show_cfg() #> '{fresh,events,responses}', '{}'::jsonb);
  v_out  text[] := '{}';
  v_lob  integer;
  v_strat text := coalesce(ev #>> array['strategyNames', coalesce(p_event.strategy, '')], p_event.strategy);
begin
  select pc.lobby_level into v_lob from public.player_companies pc where pc.company_id = p_event.company_id;
  if p_phase = 'new' then
    -- insurance: only events that can be insured carry the share in their snapshot (ADR-209)
    if p_event.definition ? 'insuredShare' then
      v_out := v_out || case when (p_event.definition ->> 'insuredShare')::numeric > 0
                             then replace(r ->> 'insured', '{pct}',
                                          public.news_show_move(round((p_event.definition ->> 'insuredShare')::numeric * 10000)::integer))
                             else r ->> 'uninsured' end;
    end if;
    v_out := v_out || case when v_strat is not null then replace(r ->> 'strategy', '{strategy}', v_strat) else r ->> 'noStrategy' end;
    if coalesce(v_lob, 0) > 0 and coalesce(ev -> 'lobbyArchetypes', '[]'::jsonb) ? p_event.archetype then
      v_out := v_out || replace(r ->> 'lobby', '{level}', v_lob::text);
    end if;
  elsif p_phase = 'won' then
    if v_strat is not null then
      v_out := v_out || replace(r ->> 'strategy', '{strategy}', v_strat);
    end if;
    if coalesce(p_event.strategy, '') like 'lobby%' and coalesce(v_lob, 0) > 0 then
      v_out := v_out || replace(r ->> 'lobbyWon', '{level}', v_lob::text);
    end if;
  else
    v_out := v_out || case when v_strat is null then r ->> 'sitOut' else replace(r ->> 'strategy', '{strategy}', v_strat) end;
    if p_event.mitigation > 0 then
      v_out := v_out || replace(r ->> 'mitigated', '{pct}', public.news_show_move(round(p_event.mitigation * 10000)::integer));
    end if;
  end if;
  return array_to_string(array_remove(v_out, null), ' ');
end;
$$;
comment on function public.news_show_event_response(public.player_company_events, text) is
  'Internal (ADR-210): what a company does about an event from outside, as the anchor says it (insurance, strategy, lobby).';

create or replace function public.news_show_event_segments(p_now timestamptz, p_win interval)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg    jsonb := public.news_show_cfg();
  ev     jsonb := coalesce(public.news_show_cfg() #> '{fresh,events}', '{}'::jsonb);
  ff     jsonb := coalesce(public.news_show_cfg() #> '{fresh,facts}', '{}'::jsonb);
  v_home text := coalesce(public.news_show_cfg() #>> '{fresh,homeCountry}', 'Nexa-Stadt');
  v_max  integer := coalesce((public.news_show_cfg() #>> '{fresh,events,max}')::integer, 0);
  v_ext  text[];
  v_out  jsonb := '[]'::jsonb;
  v_seg  jsonb;
  v_n    integer := 0;
  r      record;
begin
  if v_max <= 0 or cfg #> '{texts,worldEvent}' is null then
    return v_out;
  end if;
  select coalesce(array_agg(x ->> 'key'), '{}') into v_ext
    from jsonb_array_elements(coalesce(public.company_events_cfg() -> 'archetypes', '[]'::jsonb)) x
   where coalesce((x ->> 'external')::boolean, false);
  for r in
    select q.* from (
      -- new: started in the window
      select 'worldEvent'::text as topic, e, 'fact:event:' || e.id::text as ukey, 0 as phase,
             e.severity as sev, e.started_at as at
        from public.player_company_events e
       where e.polarity = 'crisis' and e.archetype = any (v_ext)
         and e.started_at between p_now - p_win and p_now
         and e.severity >= coalesce((ff ->> 'eventMinSeverity')::integer, 1)
      union all
      -- solved
      select 'worldEventWon', e, 'fact:eventwon:' || e.id::text, 1, e.severity, e.resolved_at
        from public.player_company_events e
       where e.polarity = 'crisis' and e.archetype = any (v_ext) and e.status = 'solved'
         and e.resolved_at between p_now - p_win and p_now
         and e.severity >= coalesce((ff ->> 'eventMinSeverity')::integer, 1)
      union all
      -- took full effect: the deadline passed without a solution
      select 'worldEventLost', e, 'fact:eventlost:' || e.id::text, 2, e.severity, e.deadline_at
        from public.player_company_events e
       where e.polarity = 'crisis' and e.archetype = any (v_ext) and e.status in ('in_force', 'expired', 'over')
         and e.resolved_at is null
         and e.deadline_at between p_now - p_win and p_now
         and e.severity >= coalesce((ff ->> 'eventMinSeverity')::integer, 1)
    ) q
    join public.player_companies pc on pc.company_id = (q.e).company_id
    where not exists (select 1 from public.news_show_used u where u.key = q.ukey)
    order by q.phase, q.sev desc, q.at desc
  loop
    exit when v_n >= v_max;
    select public.news_show_segment('world', r.topic,
             jsonb_build_object(
               'name', p.nickname, 'company', co.name,
               'event', coalesce(cfg #>> array['fresh', 'eventNames', (r.e).archetype], (r.e).archetype),
               'country', coalesce(public.country_cfg(public.company_country((r.e).company_id)) ->> 'name', v_home),
               'severity', coalesce(ev #>> array['severityNames', ((r.e).severity - 1)::text], ''),
               'response', public.news_show_event_response(r.e, case r.phase when 0 then 'new' when 1 then 'won' else 'lost' end)),
             '[]'::jsonb, '[]'::jsonb,
             jsonb_build_object('type', 'topic', 'topic', r.topic, 'group', 'world', 'player_id', pc.founder_id,
                                'name', p.nickname, 'ukey', r.ukey, 'event_id', (r.e).id, 'good', r.phase = 1))
      into v_seg
      from public.player_companies pc
      join public.companies co on co.id = pc.company_id
      join public.profiles p on p.id = pc.founder_id
     where pc.company_id = (r.e).company_id and not p.is_deactivated;
    continue when v_seg is null or position('{' in (v_seg ->> 'headline') || (v_seg ->> 'text')) > 0;
    v_out := v_out || (v_seg || jsonb_build_object('ord', coalesce((ev -> 'ords' ->> v_n)::integer, 21 + v_n)));
    v_n := v_n + 1;
  end loop;
  return v_out;
end;
$$;
comment on function public.news_show_event_segments(timestamptz, interval) is
  'Internal (ADR-210): one segment per big event from outside that hit a player company (new, solved, lost), '
  'with company, country, severity and the company''s response; not part of the topic lot.';

-- ---------------------------------------------------------------------------
-- news_show_topics(): latest full definition (20261204005700) with the two hooks of ADR-210
-- ---------------------------------------------------------------------------
create or replace function public.news_show_topics(p_now timestamptz, p_seen uuid[], p_skip uuid[], p_segments jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.news_show_cfg();
  tc       jsonb := coalesce(cfg -> 'topics', '{}'::jsonb);
  v_list   jsonb := coalesce(tc -> 'list', '{}'::jsonb);
  v_count  integer := coalesce((tc ->> 'count')::integer, 0);
  v_win    interval := make_interval(hours => coalesce((tc ->> 'windowHours')::integer, 24));
  v_today  date := (p_now at time zone 'Europe/Berlin')::date;
  v_day    text := (p_now at time zone 'Europe/Berlin')::date::text;
  v_names  jsonb := coalesce((select g.value from public.game_config g where g.key = 'nexamon_names'), '{}'::jsonb);
  v_nx     jsonb := coalesce((select g.value from public.game_config g where g.key = 'nexamon'), '{}'::jsonb);
  v_acc    jsonb;
  v_pull   jsonb := coalesce(tc #> '{cards,pullRarities}', '[]'::jsonb);
  v_hit    jsonb := coalesce(tc #> '{cards,hitRarities}', '[]'::jsonb);
  v_have   text[];
  v_last   text[];
  v_cands  jsonb;
  v_seen   uuid[] := coalesce(p_seen, '{}');
  v_skip   uuid[] := coalesce(p_skip, '{}');
  v_taken  text[] := '{}';
  v_groups text[] := '{}';
  v_out    jsonb := '[]'::jsonb;
  v_pick   jsonb;
  v_seg    jsonb;
  v_meta   jsonb;
  v_hush   bigint;
  v_player uuid;
  v_n      integer := 0;
  v_try    integer := 0;
begin
  if v_count <= 0 or v_list = '{}'::jsonb then
    return '[]'::jsonb;
  end if;
  -- players and facts that are in this show already, and the topics of the last show
  select v_seen || coalesce(array_agg((x -> 'subject' ->> 'player_id')::uuid)
                              filter (where x -> 'subject' ->> 'player_id' is not null), '{}')
    into v_seen
    from jsonb_array_elements(coalesce(p_segments, '[]'::jsonb)) x;
  select coalesce(array_agg(x -> 'subject' ->> 'ukey') filter (where x -> 'subject' ->> 'ukey' is not null), '{}')
    into v_have
    from jsonb_array_elements(coalesce(p_segments, '[]'::jsonb)) x;
  select coalesce(array_agg(x -> 'subject' ->> 'topic') filter (where x -> 'subject' ->> 'topic' is not null), '{}')
    into v_last
    from jsonb_array_elements(coalesce(
           (select s.segments from public.news_shows s where s.status = 'aired' order by s.airs_at desc limit 1), '[]'::jsonb)) x;
  select coalesce(jsonb_object_agg(x ->> 'key', x ->> 'name'), '{}'::jsonb) into v_acc
    from jsonb_array_elements(coalesce(
           (select g.value -> 'items' from public.game_config g where g.key = 'accessories'), '[]'::jsonb)) x
   where x ->> 'key' is not null and x ->> 'name' is not null;

  -- what every topic could tell: at most one candidate per topic
  select coalesce(jsonb_agg(jsonb_build_object('topic', q.topic, 'player_id', q.player_id, 'name', q.nickname,
                                               'vals', q.vals, 'ukey', q.ukey)), '[]'::jsonb)
    into v_cands
    from (
      select distinct on (c.topic) c.topic, c.player_id, p.nickname, c.ukey,
             case when p.nickname is not null then c.vals || jsonb_build_object('name', p.nickname) else c.vals end as vals
        from (
          -- ---- collectibles
          select 'cardPull'::text as topic, pk.player_id as player_id,
                 jsonb_build_object(
                   'card', coalesce(v_names ->> (x ->> 'card_key'), x ->> 'card_key'),
                   'rarity', coalesce(tc #>> array['rarityNames', x ->> 'rarity'], x ->> 'rarity'),
                   'set', coalesce(v_nx #>> array['sets', pk.set_key, 'name'], pk.set_key),
                   'packs', (select count(*) from public.nexamon_packs p2
                              where p2.player_id = pk.player_id and p2.opened_at >= p_now - v_win)) as vals,
                 'fact:npull:' || (x ->> 'copy_id') as ukey,
                 (case x ->> 'rarity' when 'legendary' then 2 else 1 end)::double precision as score
            from public.nexamon_packs pk
           cross join lateral jsonb_array_elements(case when jsonb_typeof(pk.cards) = 'array' then pk.cards else '[]'::jsonb end) x
           where pk.opened_at >= p_now - v_win and v_pull ? (x ->> 'rarity')
          union all
          select 'cardSale', coalesce(s.seller_id, s.buyer_id),
                 jsonb_build_object('seller', coalesce(sp.nickname, s.seller_ai, 'ein Händler'),
                                    'buyer', coalesce(bp.nickname, s.buyer_ai, 'ein Händler'),
                                    'card', coalesce(v_names ->> s.card_key, s.card_key),
                                    'amount', public.format_eur(s.price_cents)),
                 'fact:nsale:' || s.id::text, s.price_cents::double precision
            from public.nexamon_sales s
            left join public.profiles sp on sp.id = s.seller_id
            left join public.profiles bp on bp.id = s.buyer_id
           where s.at >= p_now - v_win and s.kind in ('market', 'ai_buy')
             and s.price_cents >= coalesce((tc #>> '{cards,minSaleCents}')::bigint, 0)
          union all
          select case when k.value_e4 >= k.day_ref_e4 then 'cardUp' else 'cardDown' end, null::uuid,
                 jsonb_build_object('card', coalesce(v_names ->> k.card_key, k.card_key),
                                    'pct', public.news_show_move(((k.value_e4 - k.day_ref_e4) * 10000 / k.day_ref_e4)::integer),
                                    'amount', public.format_eur(public.nexamon_copy_value_cents(k.value_e4, 'good', null))),
                 'fact:nmove:' || k.card_key || ':' || v_day,
                 abs((k.value_e4 - k.day_ref_e4) * 10000 / k.day_ref_e4)::double precision
            from public.nexamon_cards k
           where k.in_catalogue and k.day_ref_on = v_today
             and abs((k.value_e4 - k.day_ref_e4) * 10000 / k.day_ref_e4) >= coalesce((tc #>> '{cards,minMoveBps}')::integer, 500)
          union all
          select case when c2.grade = 10 then 'cardGradeTop' else 'cardGradeLow' end, c2.owner_id,
                 jsonb_build_object('card', coalesce(v_names ->> c2.card_key, c2.card_key), 'grade', c2.grade,
                                    'fee', public.format_eur(coalesce(c2.grading_fee_cents, 0))),
                 'fact:ngrade:' || c2.id::text,
                 public.nexamon_copy_value_cents(k.value_e4, c2.condition, c2.grade)::double precision
            from public.nexamon_copies c2
            join public.nexamon_cards k on k.card_key = c2.card_key
           where c2.owner_id is not null and c2.grade is not null and c2.graded_at >= p_now - v_win
             and (c2.grade = 10 or c2.grade <= coalesce((tc #>> '{cards,lowGradeMax}')::integer, 0))
          union all
          select 'cardDud', d.player_id, jsonb_build_object('packs', d.n, 'amount', public.format_eur(d.spent)),
                 'fact:ndud:' || d.player_id::text || ':' || v_day, d.n::double precision
            from (select pk.player_id, count(*) as n, sum(pk.price_cents)::bigint as spent,
                         bool_or(exists (select 1
                                           from jsonb_array_elements(case when jsonb_typeof(pk.cards) = 'array' then pk.cards
                                                                          else '[]'::jsonb end) x
                                          where v_hit ? (x ->> 'rarity'))) as hit
                    from public.nexamon_packs pk
                   where pk.opened_at >= p_now - v_win
                   group by pk.player_id) d
           where not d.hit and d.n >= coalesce((tc #>> '{cards,dudMinPacks}')::integer, 5)
          union all
          (select 'cardCollection', o.owner_id, jsonb_build_object('count', o.n, 'amount', public.format_eur(o.total)),
                  'fact:ncoll:' || o.owner_id::text || ':' || v_day, o.total::double precision
             from (select c2.owner_id, count(*) as n,
                          sum(public.nexamon_copy_value_cents(k.value_e4, c2.condition, c2.grade))::bigint as total
                     from public.nexamon_copies c2
                     join public.nexamon_cards k on k.card_key = c2.card_key
                     join public.profiles op on op.id = c2.owner_id and not op.is_deactivated
                    where c2.owner_id is not null
                    group by c2.owner_id) o
            where o.n >= coalesce((tc #>> '{cards,collectionMinCards}')::integer, 2)
            order by o.total desc
            limit 1)
          union all
          select 'cardAi', null::uuid, jsonb_build_object('seller', a.seller_ai, 'count', a.n, 'amount', public.format_eur(a.total)),
                 null::text, random()
            from (select l.seller_ai, count(*) as n, sum(l.price_cents)::bigint as total
                    from public.nexamon_listings l
                   where l.seller_ai is not null
                   group by l.seller_ai) a
           where a.n >= coalesce((tc #>> '{cards,aiMinListings}')::integer, 2)
          -- ---- what the feed knows: Finanzamt, listed companies, promotions, property
          union all
          select case f.kind
                   when 'tax_penalty' then case f.payload ->> 'reason' when 'late_fee' then 'taxLate'
                                                                         when 'enforcement' then 'taxEnforce' else 'taxEstimate' end
                   when 'tax_audit' then 'taxAudit'
                   when 'greedy_founder' then 'corpGreedy'
                   when 'mass_quit' then 'corpQuit'
                   when 'record_dividend' then 'corpDividend'
                   when 'board_revolt' then 'corpRevolt'
                   when 'research_done' then 'corpResearch'
                   when 'promoted' then 'pPromoted'
                   else 'pProperty' end,
                 f.actor_id,
                 jsonb_strip_nulls(jsonb_build_object(
                   'company', case when f.kind in ('home_bought', 'car_bought') then null else coalesce(f.payload ->> 'company', 'einer Firma') end,
                   'amount', case when f.payload ->> 'amount_cents' ~ '^[0-9]+$'
                                  then public.format_eur((f.payload ->> 'amount_cents')::bigint) end,
                   'pct', case when f.payload ->> 'ratio_bps' ~ '^[0-9]+(\.[0-9]+)?$'
                               then public.news_show_move(round((f.payload ->> 'ratio_bps')::numeric)::integer) end,
                   'count', case when f.kind = 'mass_quit' then f.payload ->> 'count' end,
                   'what', case f.kind
                             when 'home_bought' then 'ein neues Zuhause bezogen'
                             when 'car_bought' then 'ein neues Auto gekauft'
                                  || case when f.payload ->> 'price_cents' ~ '^[0-9]+$'
                                          then ' für ' || public.format_eur((f.payload ->> 'price_cents')::bigint) else '' end
                           end)),
                 'fact:feed:' || f.id::text, random()
            from public.feed_items f
           where f.created_at >= p_now - v_win
             and f.kind in ('tax_penalty', 'tax_audit', 'greedy_founder', 'mass_quit', 'record_dividend', 'board_revolt',
                            'research_done', 'promoted', 'home_bought', 'car_bought')
             and (f.kind <> 'mass_quit'
                  or (f.payload ->> 'count' ~ '^[0-9]+$'
                      and (f.payload ->> 'count')::integer >= coalesce((tc #>> '{corp,quitMin}')::integer, 2)))
          union all
          select 'taxStreak', pc.founder_id, jsonb_build_object('company', co.name, 'days', l.books_streak),
                 'fact:books:' || l.company_id::text || ':' || l.books_streak::text, l.books_streak::double precision
            from public.listed_companies l
            join public.player_companies pc on pc.company_id = l.company_id and pc.status = 'active'
            join public.companies co on co.id = l.company_id
           where l.books_streak >= coalesce((tc #>> '{tax,streakMinDays}')::integer, 5)
          union all
          select 'taxDebt', pc.founder_id, jsonb_build_object('company', co.name, 'amount', public.format_eur(d.due)),
                 'fact:taxdebt:' || d.company_id::text || ':' || v_day, d.due::double precision
            from (select t.company_id, sum(t.tax_cents + t.penalty_cents - t.paid_cents)::bigint as due
                    from public.company_tax_periods t
                   where t.status = 'due'
                   group by t.company_id) d
            join public.player_companies pc on pc.company_id = d.company_id and pc.status = 'active'
            join public.companies co on co.id = d.company_id
           where d.due >= coalesce((tc #>> '{tax,debtMinCents}')::bigint, 100000)
          union all
          select case when l.satisfaction <= coalesce((tc #>> '{corp,moodLow}')::numeric, 0) then 'corpMoodLow' else 'corpMoodHigh' end,
                 pc.founder_id, jsonb_build_object('company', co.name, 'value', round(l.satisfaction::numeric)::integer),
                 'fact:mood:' || l.company_id::text || ':' || v_day, abs(l.satisfaction - 50)::double precision
            from public.listed_companies l
            join public.player_companies pc on pc.company_id = l.company_id and pc.status = 'active'
            join public.companies co on co.id = l.company_id and co.phase::text = 'listed'
           where l.satisfaction <= coalesce((tc #>> '{corp,moodLow}')::numeric, 0)
              or l.satisfaction >= coalesce((tc #>> '{corp,moodHigh}')::numeric, 101)
          -- ---- persons
          union all
          select case when t.realized_pnl_cents < 0 then 'pTradeLoss' else 'pTradeWin' end, t.player_id,
                 jsonb_build_object('amount', public.format_eur(abs(t.realized_pnl_cents)), 'stock', sec.name),
                 'fact:trade:' || t.id::text, abs(t.realized_pnl_cents)::double precision
            from public.trades t
            join public.securities sec on sec.id = t.security_id
           where t.executed_at >= p_now - v_win and t.realized_pnl_cents is not null and not coalesce(t.is_wash_trade, false)
             and abs(t.realized_pnl_cents) >= coalesce((tc #>> '{person,tradeMinCents}')::bigint, 100000)
          union all
          (select 'pHourLoser', w.entity_id,
                  jsonb_build_object('amount', public.format_eur(w.first_nw - w.last_nw),
                                     'pct', public.news_show_move(((w.first_nw - w.last_nw) * 10000 / w.first_nw)::integer)),
                  'fact:hour:' || w.entity_id::text || ':' || to_char(p_now at time zone 'UTC', 'YYYYMMDDHH24'),
                  ((w.first_nw - w.last_nw) * 10000 / w.first_nw)::double precision
             from (select l.entity_id, l.nw as last_nw, f.nw as first_nw
                     from (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                            where entity_kind = 'player' and taken_at >= p_now - interval '45 minutes'
                            order by entity_id, taken_at desc) l
                     join (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                            where entity_kind = 'player' and taken_at <= p_now - interval '50 minutes'
                              and taken_at >= p_now - interval '3 hours'
                            order by entity_id, taken_at desc) f using (entity_id)
                    where f.nw > 0) w
            where (w.first_nw - w.last_nw) * 10000 / w.first_nw >= coalesce((tc #>> '{person,hourMinBps}')::integer, 200)
            order by (w.first_nw - w.last_nw) * 10000 / w.first_nw desc
            limit 1)
          union all
          (select 'pHourWinner', w.entity_id,
                  jsonb_build_object('amount', public.format_eur(w.last_nw - w.first_nw),
                                     'pct', public.news_show_move(((w.last_nw - w.first_nw) * 10000 / w.first_nw)::integer)),
                  'fact:hour:' || w.entity_id::text || ':' || to_char(p_now at time zone 'UTC', 'YYYYMMDDHH24'),
                  ((w.last_nw - w.first_nw) * 10000 / w.first_nw)::double precision
             from (select l.entity_id, l.nw as last_nw, f.nw as first_nw
                     from (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                            where entity_kind = 'player' and taken_at >= p_now - interval '45 minutes'
                            order by entity_id, taken_at desc) l
                     join (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                            where entity_kind = 'player' and taken_at <= p_now - interval '50 minutes'
                              and taken_at >= p_now - interval '3 hours'
                            order by entity_id, taken_at desc) f using (entity_id)
                    where f.nw > 0) w
            where (w.last_nw - w.first_nw) * 10000 / w.first_nw >= coalesce((tc #>> '{person,hourMinBps}')::integer, 200)
            order by (w.last_nw - w.first_nw) * 10000 / w.first_nw desc
            limit 1)
          union all
          select 'pLandlord', r.owner_id, jsonb_build_object('amount', public.format_eur(r.total), 'count', r.n),
                 'fact:rent:' || r.owner_id::text || ':' || v_day, r.total::double precision
            from (select rp.owner_id, count(*) as n, sum(rp.amount_cents)::bigint as total
                    from public.rental_payments rp
                   where rp.created_at >= p_now - v_win
                   group by rp.owner_id) r
           where r.total >= coalesce((tc #>> '{person,rentMinCents}')::bigint, 10000)
          union all
          select 'pAccessory', a.player_id,
                 jsonb_build_object('count', a.n, 'amount', public.format_eur(a.total), 'item', coalesce(v_acc ->> a.top, a.top)),
                 'fact:acc:' || a.player_id::text || ':' || floor(extract(epoch from a.latest))::bigint::text, a.total::double precision
            from (select pa.player_id, count(*) as n, sum(pa.price_paid_cents)::bigint as total, max(pa.bought_at) as latest,
                         (array_agg(pa.accessory_key order by pa.price_paid_cents desc, pa.accessory_key))[1] as top
                    from public.player_accessories pa
                   where pa.bought_at >= p_now - v_win
                   group by pa.player_id) a
           where a.total >= coalesce((tc #>> '{person,accessoryMinCents}')::bigint, 100000)
          union all
          select 'pOutfit', w.player_id, jsonb_build_object('count', w.n),
                 'fact:outfit:' || w.player_id::text || ':' || w.n::text, w.n::double precision
            from (select pw.player_id, count(*) as n from public.player_accessories_worn pw group by pw.player_id) w
           where w.n >= coalesce((tc #>> '{person,outfitMin}')::integer, 4)
          union all
          select 'pBattleWon', b.winner_id,
                 jsonb_build_object('count', (select count(*) from public.battle_players bp where bp.battle_id = b.id)),
                 'fact:battle:w:' || b.id::text, random()
            from public.battles b
           where b.status::text = 'finished' and b.finished_at >= p_now - v_win and b.winner_id is not null
             and (select count(*) from public.battle_players bp where bp.battle_id = b.id) >= 2
          union all
          select 'pBattleLast', bp.player_id, jsonb_build_object('count', n.n), 'fact:battle:l:' || b.id::text, random()
            from public.battles b
           cross join lateral (select count(*) as n, max(x.rank) as worst
                                 from public.battle_players x where x.battle_id = b.id) n
            join public.battle_players bp on bp.battle_id = b.id and bp.rank = n.worst
           where b.status::text = 'finished' and b.finished_at >= p_now - v_win and n.n >= 3 and n.worst = n.n
             and bp.player_id is distinct from b.winner_id
          union all
          select 'pReroll', m.player_id, jsonb_build_object('count', m.used),
                 'fact:reroll:' || m.player_id::text || ':' || m.reset_day::text || ':' || m.used::text, m.used::double precision
            from public.mission_resets m
           where m.last_at >= p_now - v_win and m.used >= coalesce((tc #>> '{person,rerollMin}')::integer, 2)
          union all
          select 'pChatty', m.author_id, jsonb_build_object('count', m.n),
                 'fact:chat:' || m.author_id::text || ':' || v_day, m.n::double precision
            from (select fm.author_id, count(*) as n
                    from public.friend_chat_messages fm
                   where fm.created_at >= p_now - v_win and fm.author_id is not null and fm.kind = 'player'
                   group by fm.author_id) m
           where m.n >= coalesce((tc #>> '{person,chatMin}')::integer, 30)
          union all
          select 'pFriends', fr.pid, jsonb_build_object('count', fr.n),
                 'fact:friends:' || fr.pid::text || ':' || v_day || ':' || fr.n::text, fr.n::double precision
            from (select u.pid, count(*) as n
                    from public.friendships f2
                   cross join lateral (values (f2.requester_id), (f2.addressee_id)) u(pid)
                   where f2.status::text = 'accepted' and f2.responded_at >= p_now - v_win
                   group by u.pid) fr
          union all
          select 'pPoke', k.poker_id, jsonb_build_object('count', k.n),
                 'fact:poke:' || k.poker_id::text || ':' || v_day, k.n::double precision
            from (select fp.poker_id, count(*) as n from public.friend_pokes fp
                   where fp.created_at >= p_now - v_win group by fp.poker_id) k
           where k.n >= coalesce((tc #>> '{person,pokeMin}')::integer, 5)
          union all
          select 'pAbsent', p2.id,
                 jsonb_build_object('days', floor(extract(epoch from (p_now - p2.last_active_at)) / 86400)::integer),
                 'fact:gone:' || p2.id::text || ':' || floor(extract(epoch from (p_now - p2.last_active_at)) / 86400)::integer,
                 extract(epoch from (p_now - p2.last_active_at))::double precision
            from public.profiles p2
           where p2.last_active_at < p_now - make_interval(days => coalesce((cfg #>> '{gossip,absentDays}')::integer, 3))
             and p2.last_active_at > p_now - interval '30 days'
          union all
          select 'pBoss', pc.founder_id, jsonb_build_object('victim', vp.nickname, 'company', co.name),
                 'fact:job:' || j.id::text, random()
            from public.player_jobs j
            join public.player_companies pc on pc.company_id = j.company_id
            join public.companies co on co.id = j.company_id
            join public.profiles vp on vp.id = j.player_id
           where j.status::text = 'ended' and j.ended_at >= p_now - v_win and j.end_reason::text = 'fired'
             and pc.founder_id <> j.player_id
          union all
          select 'pFounderPay', pc.founder_id,
                 jsonb_build_object('company', co.name, 'amount', public.format_eur(h.total),
                                    'pct', public.news_show_move(pc.founder_payout_bps::integer)),
                 'fact:fpay:' || pc.company_id::text || ':' || v_day, h.total::double precision
            from (select ph.company_id, sum(ph.founder_payout_cents)::bigint as total
                    from public.player_company_hours ph
                   where ph.hour_start >= p_now - v_win
                   group by ph.company_id) h
            join public.player_companies pc on pc.company_id = h.company_id and pc.status = 'active'
            join public.companies co on co.id = h.company_id
           where h.total >= coalesce((tc #>> '{person,founderPayMinCents}')::bigint, 100000)
             and pc.founder_payout_bps >= coalesce((tc #>> '{person,founderPayMinBps}')::integer, 5000)
          -- ---- season three (ADR-210): Weltkarte, events from outside, Talente, clones, toplists and more
          union all
          select f.topic, f.player_id, f.vals, f.ukey, f.score
            from public.news_show_topic_cands_fresh(p_now, v_win) f
          -- ---- topics without placeholders are always there
          union all
          select t.key, null::uuid, '{}'::jsonb, null::text, 0::double precision
            from jsonb_each(v_list) t
           where jsonb_array_length(coalesce(t.value -> 'slots', '[]'::jsonb)) = 0
        ) c
        left join public.profiles p on p.id = c.player_id
       where coalesce((v_list #>> array[c.topic, 'weight'])::numeric, 0) > 0
         and (c.player_id is null or (p.id is not null and not p.is_deactivated and c.player_id <> all (v_seen)))
         and (c.ukey is null
              or (c.ukey <> all (v_have) and not exists (select 1 from public.news_show_used u where u.key = c.ukey)))
       order by c.topic, (c.player_id = any (v_skip)) nulls first, c.score desc, random()) q;

  -- ADR-210: every big event from outside that hit a player company has its own segment (company news: the
  -- founder may still be in another story)
  v_out := public.news_show_event_segments(p_now, v_win);

  -- the draw: not what ran in the last show while there is something else, groups that are not in the show yet
  -- first, then the weighted lot (pickTopics in src/lib/sim/news-show.ts)
  loop
    exit when v_n >= v_count or v_try >= 60;
    v_try := v_try + 1;
    v_pick := null;
    select c into v_pick
      from jsonb_array_elements(v_cands) c
     where c ->> 'topic' <> all (v_taken)
       and (c ->> 'player_id' is null or (c ->> 'player_id')::uuid <> all (v_seen))
     order by (c ->> 'topic' = any (v_last))::integer,
              (select count(*) from unnest(v_groups) g where g = v_list #>> array[c ->> 'topic', 'group']),
              -ln(greatest(random(), 1e-9)) / (v_list #>> array[c ->> 'topic', 'weight'])::double precision
     limit 1;
    exit when v_pick is null;
    v_taken := v_taken || (v_pick ->> 'topic');
    v_meta := v_list -> (v_pick ->> 'topic');
    v_player := (v_pick ->> 'player_id')::uuid;
    v_hush := case when v_meta ->> 'tone' = 'bad' and v_meta ->> 'group' in ('person', 'cards') and v_player is not null
                   then coalesce((tc ->> 'hushMoneyCents')::bigint, 0) else 0 end;
    v_seg := public.news_show_segment(coalesce(v_meta ->> 'kind', 'world'), v_pick ->> 'topic', v_pick -> 'vals',
      case when v_hush > 0 then jsonb_build_array(jsonb_build_object('label', '+' || public.format_eur(v_hush) || ' Schmerzensgeld', 'tone', 'gain'))
           else '[]'::jsonb end,
      case when v_hush > 0 then jsonb_build_array(jsonb_build_object('type', 'cash', 'player_id', v_player, 'cents', v_hush))
           else '[]'::jsonb end,
      jsonb_strip_nulls(jsonb_build_object('type', 'topic', 'topic', v_pick ->> 'topic', 'group', v_meta ->> 'group',
                                           'player_id', v_player, 'name', v_pick ->> 'name', 'ukey', v_pick ->> 'ukey',
                                           'good', v_meta ->> 'tone' = 'good')));
    -- a text with a placeholder left over (a fact without the value its script needs) is never aired
    if v_seg is null or position('{' in (v_seg ->> 'headline') || (v_seg ->> 'text')) > 0 then
      continue;
    end if;
    v_seg := public.news_show_segue(v_seg);
    v_out := v_out || (v_seg || jsonb_build_object('ord', coalesce((tc -> 'ords' ->> v_n)::integer, 85 + v_n)));
    v_n := v_n + 1;
    v_groups := v_groups || coalesce(v_meta ->> 'group', '');
    if v_player is not null then
      v_seen := v_seen || v_player;
    end if;
  end loop;
  return v_out;
end;
$$;

comment on function public.news_show_topics(timestamptz, uuid[], uuid[], jsonb) is
  'Internal: the topic segments of a news show (ADR-169, ADR-210): collectibles, Finanzamt, listed companies, personal '
  'news, odd bits, Weltkarte, Talente and toplists, drawn by weight with rotation; reads facts only, the caller sorts '
  'them into the show by "ord".';

-- ---------------------------------------------------------------------------
-- The chat reacts to what is on air (freshChatLines in src/lib/sim/news-chat.ts)
-- ---------------------------------------------------------------------------
create or replace function public.news_show_fresh_chat(p_show_id bigint, p_now timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.news_show_cfg();
  fc      jsonb := public.news_show_cfg() #> '{fresh,chat}';
  names   jsonb := coalesce(public.news_show_cfg() #> '{chat,bots,names}', '[]'::jsonb);
  s       public.news_shows;
  v_cut   timestamptz;
  v_intro numeric := coalesce((cfg ->> 'introSeconds')::numeric, 8);
  v_seg   numeric := greatest(1, coalesce((cfg ->> 'segmentSeconds')::numeric, 22));
  v_per   integer;
  v_max   integer;
  v_lines integer := 0;
  v_n     integer := 0;
  v_k     integer;
  v_taken text[] := '{}';
  seg     jsonb;
  v_idx   bigint;
  v_key   text;
  v_vals  jsonb;
  v_start numeric;
  v_t     text;
  v_poll  record;
  v_nn    integer := 0;
begin
  select * into s from public.news_shows where id = p_show_id;
  if s.id is null or s.status <> 'aired' or fc is null or jsonb_array_length(names) = 0 then
    return 0;
  end if;
  v_nn := jsonb_array_length(names);
  v_cut := public.news_show_fresh_cutoff(s.id);
  v_per := greatest(0, coalesce((fc ->> 'perSegment')::integer, 0));
  v_max := greatest(0, coalesce((fc ->> 'maxPerShow')::integer, 0));

  for seg, v_idx in select x, ord from jsonb_array_elements(s.segments) with ordinality t(x, ord) loop
    v_key := coalesce(seg -> 'subject' ->> 'topic', seg ->> 'kind');
    v_vals := coalesce(seg -> 'subject' -> 'values', '{}'::jsonb);
    v_start := v_intro + (v_idx - 1) * v_seg;
    -- the lines of its topic (else of its kind): complete, not twice in a show, the ones of the last shows last
    for v_t in
      select l
        from jsonb_array_elements_text(coalesce(fc -> 'topics' -> (seg -> 'subject' ->> 'topic'),
                                                fc -> 'kinds' -> (seg ->> 'kind'), '[]'::jsonb)) l
        left join public.news_show_used u on u.key = 'c:' || md5(l)
       where l <> all (v_taken) and position('{' in public.news_show_fill(l, v_vals)) = 0
       order by coalesce(u.used_at > v_cut, false), u.used_at nulls first, random()
       limit least(v_per, greatest(0, v_max - v_lines))
    loop
      v_taken := v_taken || v_t;
      v_lines := v_lines + 1;
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      values (null, names ->> floor(random() * v_nn)::integer, left(public.news_show_fill(v_t, v_vals), 300),
              p_now + make_interval(secs => (v_start + 2 + random() * greatest(1, v_seg - 4))::double precision));
      insert into public.news_show_used (key, used_at) values ('c:' || md5(v_t), clock_timestamp())
      on conflict (key) do update set used_at = excluded.used_at;
      v_n := v_n + 1;
    end loop;
    -- an emote storm after a big pull
    if coalesce(fc #> '{burst,on}', '[]'::jsonb) ? v_key then
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      select null, names ->> floor(random() * v_nn)::integer,
             fc #>> array['burst', 'emotes', floor(random() * jsonb_array_length(fc #> '{burst,emotes}'))::integer::text],
             p_now + make_interval(secs => (v_start + 3 + random() * coalesce((fc #>> '{burst,seconds}')::numeric, 5))::double precision)
        from generate_series(1, public.rand_between(coalesce((fc #>> '{burst,countMin}')::integer, 0),
                                                    coalesce((fc #>> '{burst,countMax}')::integer, 0))) g
       where jsonb_array_length(coalesce(fc #> '{burst,emotes}', '[]'::jsonb)) > 0;
      get diagnostics v_k = row_count;
      v_n := v_n + v_k;
    end if;
  end loop;

  -- at most one poll per show, on a segment it fits, with a few votes
  if random() * 10000 < coalesce((fc #>> '{polls,chanceBps}')::integer, 0) then
    select t.ord as idx, p ->> 'question' as question, public.news_show_fill(p ->> 'question', coalesce(t.x -> 'subject' -> 'values', '{}'::jsonb)) as body
      into v_poll
      from jsonb_array_elements(s.segments) with ordinality t(x, ord)
      cross join jsonb_array_elements(coalesce(fc #> '{polls,list}', '[]'::jsonb)) p
      left join public.news_show_used u on u.key = 'c:' || md5(p ->> 'question')
     where (p -> 'on') ? coalesce(t.x -> 'subject' ->> 'topic', t.x ->> 'kind')
       and position('{' in public.news_show_fill(p ->> 'question', coalesce(t.x -> 'subject' -> 'values', '{}'::jsonb))) = 0
       and (u.used_at is null or u.used_at <= v_cut)
     order by random()
     limit 1;
    if v_poll.idx is not null then
      v_start := v_intro + (v_poll.idx - 1) * v_seg;
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      values (null, left(coalesce(fc #>> '{polls,host}', 'NEXA-Umfrage'), 40), left(v_poll.body, 300),
              p_now + make_interval(secs => (v_start + 4)::double precision));
      insert into public.news_show_used (key, used_at) values ('c:' || md5(v_poll.question), clock_timestamp())
      on conflict (key) do update set used_at = excluded.used_at;
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      select null, names ->> floor(random() * v_nn)::integer,
             fc #>> array['polls', 'votes', floor(random() * jsonb_array_length(fc #> '{polls,votes}'))::integer::text],
             p_now + make_interval(secs => (v_start + 6 + random() * greatest(1, v_seg - 8))::double precision)
        from generate_series(1, public.rand_between(coalesce((fc #>> '{polls,votesMin}')::integer, 0),
                                                    coalesce((fc #>> '{polls,votesMax}')::integer, 0))) g
       where jsonb_array_length(coalesce(fc #> '{polls,votes}', '[]'::jsonb)) > 0;
      get diagnostics v_k = row_count;
      v_n := v_n + 1 + v_k;
    end if;
  end if;
  return v_n;
end;
$$;
comment on function public.news_show_fresh_chat(bigint, timestamptz) is
  'Internal (ADR-210): the made-up viewers react to each segment of a show that went on air: lines by topic or kind, '
  'at most one poll with votes, emotes after a big pull. Real players'' chat is never touched.';

-- When a show goes on air (news_show_start sets status and started_at), its reactions are written for the whole show.
create or replace function public.news_shows_fresh_chat()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'aired' and old.status = 'scheduled' then
    perform public.news_show_fresh_chat(new.id, coalesce(new.started_at, now()));
  end if;
  return null;
end;
$$;
drop trigger if exists news_shows_fresh_chat on public.news_shows;
create trigger news_shows_fresh_chat
  after update of status on public.news_shows
  for each row execute function public.news_shows_fresh_chat();

revoke all on function public.news_show_fresh_cutoff(bigint) from public, anon, authenticated;
revoke all on function public.news_show_pick(text) from public, anon, authenticated;
revoke all on function public.news_show_segue(jsonb) from public, anon, authenticated;
revoke all on function public.news_show_topic_cands_fresh(timestamptz, interval) from public, anon, authenticated;
revoke all on function public.news_show_topics(timestamptz, uuid[], uuid[], jsonb) from public, anon, authenticated;
revoke all on function public.news_show_fresh_chat(bigint, timestamptz) from public, anon, authenticated;
revoke all on function public.news_show_event_segments(timestamptz, interval) from public, anon, authenticated;
revoke all on function public.news_show_event_response(public.player_company_events, text) from public, anon, authenticated;
revoke all on function public.news_shows_fresh_chat() from public, anon, authenticated;
grant execute on function public.news_show_topics(timestamptz, uuid[], uuid[], jsonb) to service_role;

-- ===== supabase/migrations/20261204010500_flyer_cap.sql =====
-- =============================================================================
-- Flyer price cap for small companies (ADR-212)
-- =============================================================================
-- A campaign costs costHours x the demand of the last hour (ADR-097), and the demand comes from the heavy-tailed
-- market size drawn at founding. About 5.6 % of new garages could not afford even the flyer from their starting cash.
-- The flyer of a small company (legal form in startups.campaigns.flyerCapTiers, or company value below
-- flyerCapBelowValueCents) now costs at most flyerCapCents, before the founder's ad_agency discount. Online and TV
-- campaigns and bigger companies pay the normal price.
-- company_campaign_cost_cents() is the one price used by start_campaign() and company_campaign_costs() (the price on
-- the campaign card), so both show and charge the same capped price. This is the 000700 definition with the cap.
-- New internal helper: campaign_cap_cents(). No new RPCs, no new error keys. Idempotent.

-- ADR-212: highest price of a campaign kind for a company, null when it pays the normal price
create or replace function public.campaign_cap_cents(p_company uuid, p_kind text)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select case
           when p_kind <> 'flyer' then null
           when exists (select 1 from public.player_companies pc
                         where pc.company_id = p_company
                           and (coalesce(x.c -> 'flyerCapTiers', '["garage"]'::jsonb) ? pc.tier
                                or public.company_value_cents(p_company)
                                   < public.cfg_num(x.c, '{flyerCapBelowValueCents}', 100000000)))
             then public.cfg_num(x.c, '{flyerCapCents}', 200000)::bigint
         end
    from (select public.campaigns_cfg() as c) x;
$$;
comment on function public.campaign_cap_cents(uuid, text) is
  'Internal (ADR-212): highest flyer price of a small company (garage or value below the threshold), else null.';

-- campaign_cost_cents, at most the cap of a small company (ADR-212), less the founder's ad_agency, in whole euros
create or replace function public.company_campaign_cost_cents(p_company uuid, p_kind text)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select (round((x.c - public.apply_bps(x.c, public.company_upgrade_bps(p_company, 'ad_agency')))::numeric / 100) * 100)::bigint
    from (select least(public.campaign_cost_cents(p_kind, public.company_campaign_base_cents(p_company)),
                       public.campaign_cap_cents(p_company, p_kind)) as c) x;
$$;
comment on function public.company_campaign_cost_cents(uuid, text) is
  'Internal (ADR-097, ADR-134, ADR-212): price of a marketing campaign of a company: the flyer of a small company '
  'capped, then the founder''s ad_agency upgrade.';

do $$
declare
  f text;
begin
  foreach f in array array['public.campaign_cap_cents(uuid, text)', 'public.company_campaign_cost_cents(uuid, text)'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;

-- ===== supabase/migrations/20261204010600_company_hour_costs.sql =====
-- =============================================================================
-- Fixed and variable costs of the last closed hour (ADR-208, Nachtrag)
-- =============================================================================
-- The dashboard shows two tiles "Fixkosten" and "Variable Kosten" per hour; tapping one opens where the money went.
-- get_company_hour_costs() reads the last row of player_company_hours of the own company and the ledger bookings of
-- that hour (exact idempotency keys of player_company_close_hour, listed_hour_costs and world_hour_costs), so the parts
-- add up to what the hour really paid. Nothing is written; no schema change.
--   fixed:    wages_players, wages_ai, talents (current hourly cost of the hired talents), rent (base fixed costs with
--             the country factor), marketing, upkeep (research, products, expansion, benefits of listed companies),
--             advisor, subsidiaries, insurance, overhead (ADR-209: both are a share of the own revenue and part of
--             cogs_cents; split out with macro_friction at today's company value)
--   variable: goods (cogs_cents minus insurance and overhead), profit_share (ADR-206, job_rewards of the hour),
--             location_fee (Standortgebühr, ADR-208), supply_fees (supply contracts, ADR-098)
-- New RPC (founder): get_company_hour_costs(). Idempotent.

create or replace function public.company_hour_costs_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  h        public.player_company_hours;
  pc       public.player_companies;
  v_acc    uuid;
  k        text;
  v_lx     jsonb := '{}'::jsonb;
  v_subs   bigint := 0;
  v_fee    bigint := 0;
  v_upkeep bigint := 0;
  v_adv    bigint := 0;
  v_rent   bigint;
  v_tal    bigint;
  v_share  bigint;
  v_own    bigint;
  v_total  double precision;
  v_prem   double precision;
  v_ins    bigint;
  v_over   bigint;
  v_goods  bigint;
  v_fixed  jsonb;
  v_var    jsonb;
  r        record;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select * into h from public.player_company_hours x where x.company_id = p_company order by x.hour_start desc limit 1;
  if h.company_id is null then
    return jsonb_build_object('company_id', p_company, 'hour_start', null, 'revenue_cents', 0, 'fixed_cents', 0,
                              'variable_cents', 0, 'fixed', '[]'::jsonb, 'variable', '[]'::jsonb);
  end if;
  v_acc := public.company_cash_account(p_company);
  k := 'pch:' || p_company::text || ':' || to_char(h.hour_start at time zone 'UTC', 'YYYYMMDDHH24');
  -- what left the cash under the hour's exact keys
  for r in select t.idempotency_key as key, coalesce(sum(-e.amount_cents), 0)::bigint as cents
             from public.ledger_transactions t
             join public.ledger_entries e on e.transaction_id = t.id and e.account_id = v_acc
            where t.idempotency_key = any (array[k || ':lx:research', k || ':lx:product', k || ':lx:expansion',
                                                 k || ':lx:benefit', k || ':lx:advisor', k || ':world:subs',
                                                 k || ':world:fee'])
            group by t.idempotency_key loop
    if r.key = k || ':lx:advisor' then
      v_adv := greatest(0, r.cents);
    elsif r.key = k || ':world:subs' then
      v_subs := greatest(0, r.cents);
    elsif r.key = k || ':world:fee' then
      v_fee := greatest(0, r.cents);
    else
      v_upkeep := v_upkeep + greatest(0, r.cents);
    end if;
  end loop;
  -- fixed_cents holds the base fixed costs plus the listed and world costs of the hour
  v_rent := greatest(0, h.fixed_cents - v_upkeep - v_adv - v_subs - v_fee);
  select coalesce(sum(public.talent_offer_cost(t.wage_cents, t.benefits)), 0)::bigint into v_tal
    from public.talents t where t.company_id = p_company;
  select coalesce(sum(j.amount_cents), 0)::bigint into v_share
    from public.job_rewards j
   where j.company_id = p_company and j.kind = 'profit_share'
     and j.source_key like 'profit:%:' || floor(extract(epoch from h.hour_start))::bigint::text;
  -- ADR-209: overhead and the insurance premium move with the own revenue inside cogs_cents
  v_own := greatest(0, h.revenue_cents - coalesce(h.contract_revenue_cents, 0) - coalesce(h.strength_bonus_cents, 0));
  v_total := coalesce((public.macro_friction(public.company_worth_cents(p_company), pc.insurance_level)
                       ->> 'extra_cost_share')::double precision, 0);
  v_prem := public.cfg_num(public.macro_cfg(),
                           array['insurance', 'levels', greatest(0, coalesce(pc.insurance_level, 0))::text, 'premiumBps'], 0)
            / 10000.0;
  v_ins := floor(v_own * least(v_prem, v_total))::bigint;
  v_over := floor(v_own * greatest(0, v_total - v_prem))::bigint;
  if v_ins + v_over > h.cogs_cents then
    v_ins := case when v_ins + v_over > 0 then h.cogs_cents * v_ins / (v_ins + v_over) else 0 end;
    v_over := h.cogs_cents - v_ins;
  end if;
  v_goods := greatest(0, h.cogs_cents - v_ins - v_over);
  v_fixed := jsonb_build_array(
    jsonb_build_object('key', 'wages_players', 'cents', coalesce(h.player_wages_paid_cents, 0)),
    jsonb_build_object('key', 'wages_ai', 'cents', coalesce(h.ai_wages_paid_cents, 0)),
    jsonb_build_object('key', 'talents', 'cents', v_tal),
    jsonb_build_object('key', 'rent', 'cents', v_rent),
    jsonb_build_object('key', 'marketing', 'cents', coalesce(h.marketing_cents, 0)),
    jsonb_build_object('key', 'upkeep', 'cents', v_upkeep),
    jsonb_build_object('key', 'advisor', 'cents', v_adv),
    jsonb_build_object('key', 'subsidiaries', 'cents', v_subs),
    jsonb_build_object('key', 'insurance', 'cents', v_ins),
    jsonb_build_object('key', 'overhead', 'cents', v_over));
  v_var := jsonb_build_array(
    jsonb_build_object('key', 'goods', 'cents', v_goods),
    jsonb_build_object('key', 'profit_share', 'cents', v_share),
    jsonb_build_object('key', 'location_fee', 'cents', v_fee),
    jsonb_build_object('key', 'supply_fees', 'cents', coalesce(h.supply_fee_paid_cents, 0)));
  return jsonb_build_object(
    'company_id', p_company,
    'hour_start', h.hour_start,
    'revenue_cents', h.revenue_cents,
    'fixed_cents', (select coalesce(sum((x ->> 'cents')::bigint), 0) from jsonb_array_elements(v_fixed) x),
    'variable_cents', (select coalesce(sum((x ->> 'cents')::bigint), 0) from jsonb_array_elements(v_var) x),
    'fixed', v_fixed,
    'variable', v_var);
end;
$$;
revoke all on function public.company_hour_costs_json(uuid) from public, anon, authenticated;

create or replace function public.get_company_hour_costs()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.company_hour_costs_json(public.require_own_company());
end;
$$;
comment on function public.get_company_hour_costs() is
  'RPC (founder): fixed and variable costs of the last closed hour of the own company, each split by where they '
  'arise (ADR-208, Nachtrag).';
revoke all on function public.get_company_hour_costs() from public, anon;
grant execute on function public.get_company_hour_costs() to authenticated;

commit;
